import {
  useState,
  useMemo,
  useEffect,
  useCallback,
  lazy,
  Suspense,
} from "react";
import { useLocation, Routes, Route, Navigate } from 'react-router-dom';
import { useNavigation } from "./hooks/useNavigation";
import { useReviewSession } from "./hooks/useReviewSession";
import { useFilteredCards } from "./hooks/useFilteredCards";
import { useGlobalShortcuts } from "./hooks/useGlobalShortcuts";
import type { Card } from "./types";
import { calculateFsrsProgress } from "./algorithms/fsrs";
import { getLinkFeedback } from "./linkFeedback";
import { useAppInitialization } from "./hooks/useAppInitialization";
import { useFirebaseSync } from './hooks/useFirebaseSync';
import { useAuth } from "./context/AuthContext";

import { AddDataPage } from "./components/AddDataPage";
import { AppLayout } from "./components/AppLayout";
import { ErrorBoundary } from "./components/ErrorBoundary";
import { LoginPage } from "./components/LoginPage";
import { UpsellModal } from "./components/UpsellModal";
import { OnboardingWizard } from "./components/OnboardingWizard";
import { useTier } from "./lib/useTier";
import { scheduleLocalNotification } from "./lib/notifications";
import { HomePage } from "./components/HomePage";
import { StatsPage } from "./components/StatsPage";
import { ReviewHubPage } from "./components/ReviewHubPage";
import { AppModals } from "./components/AppModals";
import { CircleNotch } from "@phosphor-icons/react";
import { ThemeProvider } from "./context/ThemeContext";
import { useCurrentSection } from "./hooks/useCurrentSection";

// Lazy load heavy components
const CoursesPage = lazy(() => import("./components/CoursesPage").then(m => ({ default: m.CoursesPage })));
const NetworkView = lazy(() =>
  import("./components/NetworkView").then((module) => ({
    default: module.NetworkView,
  })),
);
const SettingsPage = lazy(() => import("./components/SettingsPage"));
const BrowsePage = lazy(() =>
  import("./components/BrowsePage").then((module) => ({
    default: module.BrowsePage,
  })),
);

function LoadingFallback() {
  return (
    <div className="flex items-center justify-center h-full w-full min-h-[50vh]">
      <div className="flex flex-col items-center gap-4 text-slate-400">
        <CircleNotch className="animate-spin" size={48} />
        <p className="text-sm font-medium">Chargement...</p>
      </div>
    </div>
  );
}

import { useCardStore } from "./store/useCardStore";
import { useUIStore } from "./store/useUIStore";
import { useTaskStore } from "./store/useTaskStore";

function AppContent() {
  const { user } = useAuth();
  const [bypassLogin, setBypassLogin] = useState(false);
  const { canAccess } = useTier();
  const [upsellFeature, setUpsellFeature] = useState<string | null>(null);
  const { hasCompletedOnboarding } = useUIStore();

  const {
    cards,
    handleSaveCard,
    handleDeleteCard,
    confirmDelete,
    handleBatchImport,
    handleSuppressConnections,
    editingCard,
    setEditingCard,
    cardToDelete,
    setCardToDelete,
  } = useCardStore();

  const {
    activeFilters,
    searchQuery,
    viewMode,
    addDataMode,
    setAddDataMode,
  } = useUIStore();

  const activeSection = useCurrentSection();

  const location = useLocation();



  const { embeddingsReady } = useAppInitialization();

  // Activer la synchronisation Firebase en temps réel
  useFirebaseSync();

  // Auto-complete onboarding if the user already has cards (e.g. connected on a new device)
  useEffect(() => {
    if (!hasCompletedOnboarding && cards.length > 0) {
      useUIStore.getState().completeOnboarding();
    }
  }, [cards.length, hasCompletedOnboarding]);

  // Check due cards for local notification
  useEffect(() => {
    if (!hasCompletedOnboarding) return;

    const dueCount = cards.filter(
      (c) =>
        c.progress?.status === "review" &&
        c.progress.dueDate &&
        new Date(c.progress.dueDate) <= new Date()
    ).length;

    if (dueCount > 0) {
      scheduleLocalNotification(
        "Extnd. — Révisions FSRS",
        `Vous avez ${dueCount} fiche${dueCount > 1 ? 's' : ''} à réviser aujourd'hui. Ne perdez pas le fil !`,
        '/review'
      );
    }
  }, [cards, hasCompletedOnboarding]);

  const {
    selectedCardId,
    setSelectedCardId,
    pendingClusterReview,
    setPendingClusterReview,
    networkPanelPinned,
    setNetworkPanelPinned,
    pinnedCardId,
    setPinnedCardId,
    navigateSection,
    startClusterReviewMode,
  } = useNavigation();

  const {
    reviewSession,
    setReviewSession,
    reviewSessionCards,
    startFSRSReview,
    startIntensiveReview,
    startCourseReview,
    startQuizReview,
    startCustomReview,
  } = useReviewSession(cards);

  const handleEditCard = useCallback(
    (card: Card) => {
      setEditingCard(card);
      setAddDataMode("edit");
      setSelectedCardId(null);
    },
    [setEditingCard, setAddDataMode, setSelectedCardId],
  );

  const handleSaveCardWrapped = useCallback(
    (card: Card) => {
      handleSaveCard(card);
      setAddDataMode("none");
      setEditingCard(null);
    },
    [handleSaveCard, setAddDataMode, setEditingCard],
  );

  // Silent variant used for review ratings: does NOT close the edit modal or reset addDataMode.
  const handleSaveCardSilent = useCallback(
    (card: Card) => {
      handleSaveCard(card);
    },
    [handleSaveCard],
  );

  const confirmDeleteWrapped = useCallback(() => {
    if (cardToDelete) {
      if (selectedCardId === cardToDelete.id) {
        setSelectedCardId(null);
      }
      confirmDelete();
    }
  }, [cardToDelete, selectedCardId, confirmDelete, setSelectedCardId]);

  const handleBatchImportWrapped = useCallback(
    async (newCards: Card[]) => {
      await handleBatchImport(newCards);
      navigateSection("cards");
    },
    [handleBatchImport, navigateSection],
  );

  const selectedCard = useMemo(() => {
    const panelCardId =
      networkPanelPinned && pinnedCardId ? pinnedCardId : selectedCardId;
    if (!panelCardId) return null;
    return cards.find((c) => c.id === panelCardId) ?? null;
  }, [cards, selectedCardId, networkPanelPinned, pinnedCardId]);

  const handleRateCard = useCallback(
    (cardId: string, rating: 1 | 2 | 3 | 4) => {
      const card = cards.find((c) => c.id === cardId);
      if (!card) return;
      const isCourseType = card.nodeType === 'course' || card.nodeType === 'concept';
      const nextProgress = calculateFsrsProgress(card.progress, rating, isCourseType);
      // Use silent save to avoid closing an open edit form during a concurrent review session.
      handleSaveCardSilent({
        ...card,
        progress: nextProgress,
        updatedAt: Date.now(),
      });
    },
    [cards, handleSaveCardSilent],
  );

  const isNetworkContext =
    activeSection === "network" ||
    (activeSection === "cards" &&
      (viewMode === "network" || viewMode === "split"));

  const { filteredCards, searchResultIds } = useFilteredCards(cards, searchQuery, activeFilters);

  useGlobalShortcuts({
    isNetworkContext,
    networkPanelPinned,
    setSelectedCardId,
    navigateSection,
  });

  const onResumeTask = useCallback((taskId: string) => {
    const taskStore = useTaskStore.getState();
    const task = taskStore.pausedTasks.find(t => t.id === taskId);
    if (!task) return;

    if (task.type === 'review_session') {
      const state = task.state as { cardIds: string[], currentIndex: number, title?: string };
      if (!state.cardIds) return;

      const cardMap = new Map(cards.map(c => [c.id, c]));
      const sessionCards = state.cardIds.map(id => cardMap.get(id)).filter((c): c is Card => !!c);

      if (sessionCards.length > 0) {
        setReviewSession({
          title: state.title || 'Session de révision',
          cardIds: state.cardIds,
          initialIndex: state.currentIndex || 0
        });
      }
      taskStore.handleRemoveTask(taskId);
    }
  }, [cards, setReviewSession]);

  const renderBrowsePage = (isNetworkOnly: boolean) => (
    <BrowsePage
      isNetworkOnly={isNetworkOnly}
      networkPanelCard={isNetworkContext ? selectedCard : null}
      networkPanelPinned={networkPanelPinned}
      onNetworkPanelClose={() => {
        setSelectedCardId(null);
        if (!networkPanelPinned) {
          setPinnedCardId(null);
        }
      }}
      onNetworkPanelPinToggle={() => {
        setNetworkPanelPinned((prev) => {
          const next = !prev;
          if (next && selectedCard) {
            setPinnedCardId(selectedCard.id);
          }
          if (!next) {
            setPinnedCardId(null);
          }
          return next;
        });
      }}
      renderNetworkView={() => (
        <Suspense fallback={<LoadingFallback />}>
          <NetworkView
            cards={filteredCards}
            onNodeClick={(id) => {
              if (networkPanelPinned) {
                setPinnedCardId(id);
              }
              setSelectedCardId(id);
            }}
            searchQuery={searchQuery}
            highlightedIds={
              searchResultIds ? new Set(searchResultIds) : undefined
            }
            activeFilters={activeFilters}
            onSuppressConnections={handleSuppressConnections}
            semanticReady={embeddingsReady}
            vetoPairs={getLinkFeedback().vetoPairs}
            typeCompat={getLinkFeedback().typePairScores}
            activeNodeId={selectedCard?.id}
            pendingClusterReview={pendingClusterReview}
            onStartClusterReview={(clusterNodeIds) => {
              setPendingClusterReview(false);
              if (clusterNodeIds.length === 0) return;
              setReviewSession({
                cardIds: clusterNodeIds,
                title: "Révision par Cluster",
              });
            }}
          />
        </Suspense>
      )}
    />
  );

  const renderMainContent = () => {
    return (
      <Routes>
        <Route path="/" element={<HomePage onNavigate={navigateSection} onAddCard={() => navigateSection("add")} />} />
        <Route path="/dashboard" element={<Navigate to="/" replace />} />

        <Route path="/settings" element={<SettingsPage onClose={() => navigateSection("dashboard")} />} />
        <Route path="/stats" element={<StatsPage />} />
        <Route path="/add" element={
          <AddDataPage
            existingCards={cards}
            onSave={handleSaveCardWrapped}
            onImport={handleBatchImportWrapped}
          />
        } />

        <Route path="/review" element={
          <ReviewHubPage
            onSelectFSRS={startFSRSReview}
            onSelectCluster={startClusterReviewMode}
            onSelectIntensive={startIntensiveReview}
            onSelectCourse={(courseId) => {
              const course = cards.find(c => c.id === courseId);
              startCourseReview(courseId, `Révision — ${course?.title || 'Cours'}`);
            }}
            onSelectQuiz={startQuizReview}
            onSelectCustom={startCustomReview}
            hasEnoughCardsForCluster={
              cards.filter(
                (c) => c.manualConnections && c.manualConnections.length > 0,
              ).length >= 1
            }
            courses={cards.filter(c => c.nodeType === 'course')}
            allCards={cards}
          />
        } />

        <Route path="/courses" element={
          <Suspense fallback={<LoadingFallback />}>
            <CoursesPage onStartReview={(cardIds, title) => setReviewSession({ cardIds, title })} />
          </Suspense>
        } />

        <Route path="/cards" element={renderBrowsePage(false)} />
        <Route path="/browse" element={<Navigate to="/cards" replace />} />
        <Route path="/network" element={renderBrowsePage(true)} />

        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    );
  };

  const modals = (
    <AppModals
      selectedCard={selectedCard}
      isNetworkContext={isNetworkContext}
      cards={cards}
      setSelectedCardId={setSelectedCardId}
      handleEditCard={handleEditCard}
      handleDeleteCard={handleDeleteCard}
      filteredCards={filteredCards}
      selectedCardId={selectedCardId}
      addDataMode={addDataMode}
      editingCard={editingCard}
      handleSaveCardWrapped={handleSaveCardWrapped}
      handleBatchImportWrapped={handleBatchImportWrapped}
      setAddDataMode={setAddDataMode}
      setEditingCard={setEditingCard}
      cardToDelete={cardToDelete}
      confirmDeleteWrapped={confirmDeleteWrapped}
      setCardToDelete={setCardToDelete}
      reviewSession={reviewSession}
      reviewSessionCards={reviewSessionCards}
      setReviewSession={setReviewSession}
      handleRateCard={handleRateCard}
    />
  );

  if (!user && !bypassLogin) {
    return <LoginPage onBypass={() => setBypassLogin(true)} />;
  }

  return (
    <AppLayout
      onNavigate={(section) => {
        if (!canAccess(section)) {
          setUpsellFeature(section);
          return;
        }
        navigateSection(section);
      }}
      onNavigateSettings={() => navigateSection("settings")}
      pendingClusterReview={pendingClusterReview}
      onCancelClusterReview={() => setPendingClusterReview(false)}
      onResumeTask={onResumeTask}
    >
      <Suspense fallback={<LoadingFallback />}>{renderMainContent()}</Suspense>
      {modals}
      {!hasCompletedOnboarding && user && (
        <OnboardingWizard />
      )}
      <UpsellModal
        isOpen={!!upsellFeature}
        onClose={() => setUpsellFeature(null)}
        onSignIn={() => { setUpsellFeature(null); setBypassLogin(false); }}
        feature={upsellFeature ?? 'default'}
      />
    </AppLayout>
  );
}

import { IndexingProgress } from "./components/IndexingProgress";

function App() {
  return (
    <ThemeProvider>
      <ErrorBoundary>
        <AppContent />
      </ErrorBoundary>
      <IndexingProgress />
    </ThemeProvider>
  );
}

export default App;

// @ts-nocheck

interface Node {
    id: string;
}

interface Link {
    source: string | unknown;
    target: string | unknown;
    value?: number; // Weight
}

/**
 * Detects communities using a synchronous Label Propagation Algorithm (LPA).
 * Fast enough for < 5000 nodes in the main thread.
 * 
 * @param nodes List of nodes
 * @param links List of links (structural + semantic)
 * @returns Map of Node ID -> Community ID (string)
 */
export function detectCommunities(nodes: Node[], links: Link[]): Map<string, string> {
    if (nodes.length === 0) return new Map();

    const interactions = 5; // Enough for small/medium graphs to stabilize
    const labels = new Map<string, string>();
    const adjacency = new Map<string, { id: string; weight: number }[]>();

    // 1. Initialize: Each node is its own community
    nodes.forEach(node => {
        labels.set(node.id, node.id);
        adjacency.set(node.id, []);
    });

    // 2. Build Weighted Adjacency List
    links.forEach(link => {
        const sourceId = typeof link.source === 'object' ? link.source.id : link.source;
        const targetId = typeof link.target === 'object' ? link.target.id : link.target;

        // Use link value as weight
        // Structural links (value undefined) = 1.0
        // Semantic links (value ~0.7-0.9) -> Boost to ~1.75-2.25 to prioritize meaning clusters
        const weight = link.value !== undefined ? (link.value * 2.5) : 1.0;

        if (adjacency.has(sourceId)) adjacency.get(sourceId)!.push({ id: targetId, weight });
        if (adjacency.has(targetId)) adjacency.get(targetId)!.push({ id: sourceId, weight });
    });

    // 3. Propagation Loop
    const nodesList = [...nodes]; // Clone for shuffling

    for (let i = 0; i < interactions; i++) {
        // Fisher-Yates shuffle
        for (let j = nodesList.length - 1; j > 0; j--) {
            const k = Math.floor(Math.random() * (j + 1));
            [nodesList[j], nodesList[k]] = [nodesList[k], nodesList[j]];
        }

        let changes = 0;

        for (const node of nodesList) {
            const neighbors = adjacency.get(node.id);
            if (!neighbors || neighbors.length === 0) continue;

            // Count label weights
            const labelWeights = new Map<string, number>();
            neighbors.forEach(neighbor => {
                const neighborLabel = labels.get(neighbor.id)!;
                const currentWeight = labelWeights.get(neighborLabel) || 0;
                labelWeights.set(neighborLabel, currentWeight + neighbor.weight);
            });

            // Find max weight label
            let maxWeight = -1;
            let bestLabels: string[] = [];

            labelWeights.forEach((weight, label) => {
                if (weight > maxWeight) {
                    maxWeight = weight;
                    bestLabels = [label];
                } else if (Math.abs(weight - maxWeight) < 0.001) {
                    bestLabels.push(label);
                }
            });

            if (bestLabels.length > 0) {
                // If current label is not among best, pick one at random
                const currentLabel = labels.get(node.id);
                if (!bestLabels.includes(currentLabel!)) {
                    const newLabel = bestLabels[Math.floor(Math.random() * bestLabels.length)];
                    labels.set(node.id, newLabel);
                    changes++;
                }
            }
        }

        // Optimized exit: if generic stability reached
        if (changes < nodes.length * 0.02) break; // < 2% nodes changed
    }

    // 4. Renumber communities to be cleaner? (Optional, skipping for raw ID)
    return labels;
}

// @ts-nocheck

interface GraphNode {
    id: string;
}

// GraphLink interface removed as it was unused

/**
 * Dijkstra's Algorithm for "Strongest Path"
 * Cost = 1 / value (Higher confidence = Lower cost = Preferred)
 */
export function findStrongestPath(
    nodes: GraphNode[],
    links: Array<{ source: string | unknown, target: string | unknown, value?: number, type?: string }>,
    startId: string,
    endId: string
): string[] { // Returns array of Node IDs in order
    // Build adjacency list
    const adjacency = new Map<string, { target: string, cost: number }[]>();

    // Helper to get string ID safe for ForceGraph2D
    const getId = (n: string | unknown) => (n && typeof n === 'object' && n.id) ? n.id : n;

    links.forEach(link => {
        const s = getId(link.source);
        const t = getId(link.target);
        const val = link.value || 0.1; // Default low confidence if missing

        // Cost Function: Inverse Square
        // Value 1.0 (Manual/Explicit) -> Cost 1
        // Value 0.5 (Weak Semantic)   -> Cost 4
        // Value 0.1                   -> Cost 100

        // TRUST PENALTY (Secure Pathfinding)
        // Semantic/RRF links are "fuzzy" and liable to drift. 
        // We penalize them (x2 cost) so the algorithm prefers 
        // a longer path of explicit/manual links over a shortcut of weak semantic guesses.

        const isSemantic = link.type === 'semantic' || link.type === 'rrf' || link.type === 'hybrid';
        const trustPenalty = isSemantic ? 2.0 : 1.0;

        const cost = (1 / (Math.max(0.01, val) ** 2)) * trustPenalty;

        if (!adjacency.has(s)) adjacency.set(s, []);
        if (!adjacency.has(t)) adjacency.set(t, []);

        adjacency.get(s)!.push({ target: t, cost });
        adjacency.get(t)!.push({ target: s, cost }); // Undirected graph
    });

    // Dijkstra state
    const distances = new Map<string, number>();
    const previous = new Map<string, string | null>();
    const unvisited = new Set<string>();

    // Init
    nodes.forEach(node => {
        distances.set(node.id, Infinity);
        previous.set(node.id, null);
        unvisited.add(node.id);
    });

    distances.set(startId, 0);

    while (unvisited.size > 0) {
        // Find unvisited node with min distance
        let currentId: string | null = null;
        let minDist = Infinity;

        for (const id of unvisited) {
            const d = distances.get(id) ?? Infinity;
            if (d < minDist) {
                minDist = d;
                currentId = id;
            }
        }

        // If explicitly finished or unreachable
        if (currentId === null || currentId === endId) break;
        if (minDist === Infinity) break;

        unvisited.delete(currentId);

        // Relax neighbors
        const neighbors = adjacency.get(currentId) || [];
        for (const neighbor of neighbors) {
            if (!unvisited.has(neighbor.target)) continue;

            const alt = minDist + neighbor.cost;
            if (alt < (distances.get(neighbor.target) ?? Infinity)) {
                distances.set(neighbor.target, alt);
                previous.set(neighbor.target, currentId);
            }
        }
    }

    // Reconstruct path
    const path: string[] = [];
    let curr: string | null = endId;

    // Check if reachable
    if (previous.get(endId) === null && startId !== endId) {
        return []; // No path found
    }

    while (curr !== null) {
        path.unshift(curr);
        curr = previous.get(curr) || null;
    }

    return path;
}

