import React, { useMemo, useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import type { Card } from '../types';
import { MarkdownRenderer } from './MarkdownRenderer';
import { fastLexicalSearch } from '../searchIndex';
import { calculateQualityScore } from '../algorithms/qualityScoring';
import { useFocusTrap } from '../hooks/useFocusTrap';
import { useTheme } from '../context/ThemeContext';
import { DynamicIcon } from './DynamicIcon';
import { Eye, EyeSlash, X, PencilSimple, Trash, Link, CaretLeft, CaretRight } from '@phosphor-icons/react';

// --- THEME MAP ---
const lightThemeMap: Record<string, { bubble: string, tagBg: string, tagText: string, title: string, examBtn: string, fill: string }> = {
    drug: {
        bubble: 'bg-emerald-50',
        tagBg: 'bg-emerald-100/50',
        tagText: 'text-emerald-700',
        title: 'text-emerald-600',
        examBtn: 'text-emerald-600 hover:bg-emerald-50',
        fill: 'currentColor'
    },
    disease: {
        bubble: 'bg-red-50',
        tagBg: 'bg-red-100/50',
        tagText: 'text-red-700',
        title: 'text-red-600',
        examBtn: 'text-red-600 hover:bg-red-50',
        fill: 'currentColor'
    },
    anatomy: {
        bubble: 'bg-indigo-50',
        tagBg: 'bg-indigo-100/50',
        tagText: 'text-indigo-700',
        title: 'text-indigo-600',
        examBtn: 'text-indigo-600 hover:bg-indigo-50',
        fill: 'currentColor'
    },
    default: {
        bubble: 'bg-orange-50',
        tagBg: 'bg-orange-100/50',
        tagText: 'text-orange-700',
        title: 'text-orange-600',
        examBtn: 'text-orange-600 hover:bg-orange-50',
        fill: 'currentColor'
    }
};

const darkThemeMap: Record<string, { bubble: string, tagBg: string, tagText: string, title: string, examBtn: string, fill: string }> = {
    drug: {
        bubble: 'bg-emerald-900/30',
        tagBg: 'bg-emerald-900/50',
        tagText: 'text-emerald-400',
        title: 'text-emerald-400',
        examBtn: 'text-emerald-400 hover:bg-emerald-900/40',
        fill: 'currentColor'
    },
    disease: {
        bubble: 'bg-red-900/30',
        tagBg: 'bg-red-900/50',
        tagText: 'text-red-400',
        title: 'text-red-400',
        examBtn: 'text-red-400 hover:bg-red-900/40',
        fill: 'currentColor'
    },
    anatomy: {
        bubble: 'bg-indigo-900/30',
        tagBg: 'bg-indigo-900/50',
        tagText: 'text-indigo-400',
        title: 'text-indigo-400',
        examBtn: 'text-indigo-400 hover:bg-indigo-900/40',
        fill: 'currentColor'
    },
    default: {
        bubble: 'bg-orange-900/30',
        tagBg: 'bg-orange-900/50',
        tagText: 'text-orange-400',
        title: 'text-orange-400',
        examBtn: 'text-orange-400 hover:bg-orange-900/40',
        fill: 'currentColor'
    }
};

interface DetailModalProps {
    card: Card;
    allCards: Card[];
    onClose: () => void;
    onLinkClick: (cardId: string) => void;
    onEdit?: () => void;
    onDelete?: () => void;
    onNext?: () => void;
    onPrev?: () => void;
}

export const DetailModal: React.FC<DetailModalProps> = ({
    card, allCards, onClose, onLinkClick, onEdit, onDelete, onNext, onPrev,
}) => {
    const [isExamMode, setIsExamMode] = useState(false);
    const [backlinks, setBacklinks] = useState<Card[]>([]);
    const { darkMode, getCategoryIcon, getCategoryColor } = useTheme();

    const themeMap = darkMode ? darkThemeMap : lightThemeMap;
    const theme = themeMap[card.type] || themeMap.default;
    const cardColor = getCategoryColor(card.type);

    // Handle clicking outside to close
    const handleBackdropClick = (e: React.MouseEvent<HTMLDivElement>) => {
        if (e.target === e.currentTarget) {
            onClose();
        }
    };

    /* ── backlinks ── */
    useEffect(() => {
        if (!card.title) { setBacklinks([]); return; }
        let alive = true;
        fastLexicalSearch(card.title).then(res => {
            if (!alive) return;
            const ids = new Set(res.map(r => r.id));
            ids.delete(card.id);
            setBacklinks(allCards.filter(c => ids.has(c.id)).sort((a, b) => a.title.localeCompare(b.title)));
        });
        return () => { alive = false; };
    }, [card.title, card.id, allCards]);

    /* ── forward links ── */
    const forwardLinks = useMemo(() => {
        const haystack = ((card.details || '') + ' ' + (card.content || '')).toLowerCase();
        return allCards
            .filter(c => c.id !== card.id && c.title.length >= 3 && haystack.includes(c.title.toLowerCase()))
            .sort((a, b) => a.title.localeCompare(b.title));
    }, [card, allCards]);

    /* ── quality ── */
    const quality = useMemo(
        () => calculateQualityScore(card, backlinks.length + forwardLinks.length),
        [card, backlinks.length, forwardLinks.length],
    );

    /* ── keyboard ── */
    useEffect(() => {
        const handler = (e: KeyboardEvent) => {
            if (e.key === 'Escape') { onClose(); return; }
            if (e.key === 'ArrowRight' && onNext) onNext();
            else if (e.key === 'ArrowLeft' && onPrev) onPrev();
        };
        window.addEventListener('keydown', handler);
        return () => window.removeEventListener('keydown', handler);
    }, [onClose, onNext, onPrev]);

    const modalRef = useFocusTrap(true);

    return (
        <div
            className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity z-[100] flex items-center justify-center p-4 sm:p-6 gap-4 sm:gap-8"
            onClick={handleBackdropClick}
            aria-modal="true"
            role="dialog"
        >
            {/* External Previous Button */}
            <AnimatePresence>
                {onPrev && (
                    <motion.button
                        key="prev"
                        initial={{ opacity: 0, x: -8 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -8 }}
                        onClick={onPrev}
                        className="hidden sm:flex shrink-0 p-4 md:p-6 rounded-2xl bg-white/10 hover:bg-white/20 text-white backdrop-blur-md transition-all shadow-lg hover:scale-105 active:scale-95"
                        aria-label="Fiche précédente"
                    >
                        <CaretLeft className="w-8 h-8 md:w-10 md:h-10" weight="bold" />
                    </motion.button>
                )}
            </AnimatePresence>

            {/* Modal Container */}
            <motion.div
                ref={modalRef}
                key={card.id}
                initial={{ opacity: 0, scale: 0.95, y: 15 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95, y: 15 }}
                transition={{ type: 'spring', stiffness: 300, damping: 30 }}
                className={[
                    'rounded-[32px] shadow-2xl w-full max-w-4xl min-h-[600px] max-h-[90vh] flex flex-col overflow-hidden relative z-50 transform transition-all border',
                    darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'
                ].join(' ')}
            >
                {/* Category Color Bubble (Top Right) */}
                <div 
                    className="absolute -top-32 -right-32 w-80 h-80 rounded-full z-0 pointer-events-none transition-colors duration-500"
                    style={{ backgroundColor: cardColor, opacity: darkMode ? 0.15 : 0.1 }}
                ></div>

                <div className="relative z-10 flex flex-col flex-1 min-h-0 h-full w-full">

                    {/* Header Actions & Tags */}
                    <div  className="flex flex-wrap gap-4 items-start justify-between shrink-0 pt-10 px-12 pb-4">
                        <div className="flex items-center gap-3">
                            {/* Category Tag */}
                            <span className={`inline-flex items-center gap-2.5 ${theme.tagText} ${theme.tagBg} px-4 py-2 rounded-xl text-sm font-semibold tracking-wide`}>
                                <DynamicIcon name={getCategoryIcon(card.type)} size={18} color="currentColor" weight="bold" />
                                {card.type}
                            </span>

                            {/* Status indicator */}
                            <span className="flex items-center gap-1.5 text-slate-400 text-xs font-medium">
                                <span className="w-1.5 h-1.5 rounded-full" style={{ background: quality.color }}></span>
                                {quality.label} ({quality.score}%)
                            </span>
                        </div>

                        {/* Header Actions */}
                        <div className={`${['flex items-center gap-1.5 rounded-xl border shadow-sm ml-auto', darkMode ? 'bg-slate-800/80 border-slate-700/50' : 'bg-white border-slate-200/80'].join(' ')} detailmodal-style-2`} >
                            {onEdit && (
                                <button onClick={onEdit} className={`p-2 rounded-lg transition-colors ${darkMode ? 'hover:bg-slate-700 text-slate-400 hover:text-slate-200' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'}`} aria-label="Éditer" title="Éditer">
                                    <PencilSimple size={18} weight="bold" />
                                </button>
                            )}
                            {onDelete && (
                                <button onClick={onDelete} className={`p-2 rounded-lg transition-colors ${darkMode ? 'hover:bg-red-900/40 text-slate-400 hover:text-red-400' : 'text-slate-400 hover:bg-red-50 hover:text-red-400'}`} aria-label="Supprimer" title="Supprimer">
                                    <Trash size={18} weight="bold" />
                                </button>
                            )}

                            <div className={`w-[1px] h-6 mx-2 ${darkMode ? 'bg-slate-700' : 'bg-slate-200'}`}></div>

                            <button
                                onClick={() => setIsExamMode(v => !v)}
                                className={`flex items-center gap-2 px-3 py-1.5 text-sm font-bold rounded-lg transition-colors uppercase tracking-widest ${theme.examBtn} ${isExamMode ? (darkMode ? 'bg-slate-700/50' : 'bg-slate-100') : ''}`}
                            >
                                {isExamMode ? <EyeSlash size={18} weight="bold" /> : <Eye size={18} weight="bold" />}
                                Examen
                            </button>

                            <div className={`w-[1px] h-6 mx-1 ${darkMode ? 'bg-slate-700' : 'bg-slate-200'}`}></div>

                            <button onClick={onClose} className={`p-2 rounded-lg transition-colors ${darkMode ? 'hover:bg-slate-700 text-slate-400 hover:text-slate-200' : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'}`} aria-label="Fermer">
                                <X size={18} weight="bold" />
                            </button>
                        </div>
                    </div>

                    <div  className="shrink-0 mt-2 px-12 pb-6">
                        <h2 className={`text-3xl md:text-4xl font-bold leading-tight mb-2 ${theme.title}`}>
                            {card.title}
                        </h2>
                        {card.subtitle && (
                            <p className="text-xs font-semibold text-slate-400 uppercase tracking-widest">
                                {card.subtitle}
                            </p>
                        )}
                    </div>

                    <div  className={`px-12 overflow-y-auto flex-1 min-h-0 ${isExamMode ? 'exam-mode' : ''}`}>
                        <div className={`prose prose-slate prose-lg max-w-none leading-relaxed font-normal ${darkMode ? 'text-slate-300 prose-invert' : 'text-slate-600'}`}>
                            {card.imageUrl && (
                                <div className="mb-6 not-prose">
                                    <img src={card.imageUrl} alt={card.title} className="w-full rounded-2xl shadow-sm object-cover" />
                                </div>
                            )}

                            {card.content && card.content.trim() !== card.details?.trim() && (
                                <MarkdownRenderer
                                    className="max-w-none"
                                    content={card.content}
                                    onInternalLinkClick={target => {
                                        const found = allCards.find(c => c.title.toLowerCase() === target.toLowerCase());
                                        if (found) onLinkClick(found.id);
                                    }}
                                />
                            )}

                            {card.details && (
                                <div className={card.content && card.content.trim() !== card.details?.trim() ? 'mt-6' : ''}>
                                    {card.content && card.content.trim() !== card.details?.trim() && (
                                        <p className="not-prose uppercase text-xs tracking-[0.08em] font-semibold mb-3 text-slate-400">
                                            Détails
                                        </p>
                                    )}
                                    <MarkdownRenderer
                                        className="max-w-none"
                                        content={card.details}
                                        onInternalLinkClick={target => {
                                            const found = allCards.find(c => c.title.toLowerCase() === target.toLowerCase());
                                            if (found) onLinkClick(found.id);
                                        }}
                                    />
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Fixed Footer */}
                    {(forwardLinks.length > 0 || backlinks.length > 0 || (card.tags && card.tags.length > 0)) && (
                        <div  className={`px-12 py-8 shrink-0 border-t flex flex-col gap-8 relative z-20 ${darkMode ? 'border-slate-800 bg-slate-900' : 'border-slate-100 bg-white'}`}>
                            {/* Outgoing Links */}
                            {forwardLinks.length > 0 && (
                                <div>
                                    <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2 mb-4">
                                        <Link size={16} weight="bold" />
                                        Liens sortants ({forwardLinks.length})
                                    </h3>
                                    <div className="flex flex-wrap gap-3">
                                        {forwardLinks.map(link => (
                                            <button key={link.id} onClick={() => onLinkClick(link.id)} className={`inline-flex items-center px-7 py-3.5 rounded-[14px] border text-base font-semibold transition-all ${darkMode ? 'border-slate-700 text-slate-300 bg-slate-800 hover:bg-slate-700' : 'border-slate-200/80 text-slate-700 bg-white hover:border-slate-300'}`}>
                                                {link.title}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {/* Backlinks */}
                            {backlinks.length > 0 && (
                                <div>
                                    <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2 mb-4">
                                        <Link size={16} weight="bold" />
                                        Mentionné dans ({backlinks.length})
                                    </h3>
                                    <div className="flex flex-wrap gap-3">
                                        {backlinks.map(link => (
                                            <button key={link.id} onClick={() => onLinkClick(link.id)} className={`inline-flex items-center px-7 py-3.5 rounded-[14px] border text-base font-semibold transition-all ${darkMode ? 'border-slate-700 text-slate-300 bg-slate-800 hover:bg-slate-700' : 'border-slate-200/80 text-slate-700 bg-white hover:border-slate-300'}`}>
                                                {link.title}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {/* Tags */}
                            {card.tags && card.tags.length > 0 && (
                                <div className="flex flex-wrap gap-3">
                                    {card.tags.map(tag => (
                                        <span key={tag} className={`inline-flex items-center px-6 py-3 rounded-[14px] text-sm font-bold uppercase tracking-wide transition-colors ${darkMode ? 'bg-slate-800 text-slate-400 hover:bg-slate-700' : 'bg-slate-100/70 text-slate-500 hover:bg-slate-200'}`}>
                                            #{tag}
                                        </span>
                                    ))}
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </motion.div>

            {/* External Next Button (Desktop) */}
            <AnimatePresence>
                {onNext && (
                    <motion.button
                        key="next"
                        initial={{ opacity: 0, x: 8 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: 8 }}
                        onClick={onNext}
                        className="hidden sm:flex shrink-0 p-4 md:p-6 rounded-2xl bg-white/10 hover:bg-white/20 text-white backdrop-blur-md transition-all shadow-lg hover:scale-105 active:scale-95"
                        aria-label="Fiche suivante"
                    >
                        <CaretRight className="w-8 h-8 md:w-10 md:h-10" weight="bold" />
                    </motion.button>
                )}
            </AnimatePresence>

            {/* Mobile Navigation Fallback */}
            {(onPrev || onNext) && (
                <div className="fixed bottom-6 left-0 right-0 z-50 flex sm:hidden justify-center gap-4 px-4 pointer-events-none">
                    <div className="flex items-center gap-2 bg-slate-900/80 backdrop-blur-md rounded-xl p-1 pointer-events-auto shadow-xl">
                        <button disabled={!onPrev} onClick={onPrev} className={`p-3 rounded-lg text-white transition-colors ${onPrev ? 'hover:bg-white/20' : 'opacity-30 cursor-not-allowed'}`} aria-label="Fiche précédente">
                            <CaretLeft className="w-5 h-5" weight="bold" />
                        </button>
                        <div className="w-px h-6 bg-white/20"></div>
                        <button disabled={!onNext} onClick={onNext} className={`p-3 rounded-lg text-white transition-colors ${onNext ? 'hover:bg-white/20' : 'opacity-30 cursor-not-allowed'}`} aria-label="Fiche suivante">
                            <CaretRight className="w-5 h-5" weight="bold" />
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

import React from 'react';
import * as PhosphorIcons from '@phosphor-icons/react';

export const AVAILABLE_ICONS = [
    'Pill',
    'ChartLine',
    'Database',
    'Stethoscope',
    'Heart',
    'Brain',
    'DnaStrand',
    'Syringe',
    'Thermometer',
    'Flask',
    'FileText',
    'Lightning',
    'TestTube',
    'Atom'
];

interface DynamicIconProps extends Omit<React.SVGProps<SVGSVGElement>, 'name'> {
    name: string;
    size?: number | string;
    className?: string;
    weight?: "thin" | "light" | "regular" | "bold" | "fill" | "duotone";
}

export const DynamicIcon: React.FC<DynamicIconProps> = ({ name, size = 24, className, ...props }) => {
    const PhosphorIcon = (PhosphorIcons as unknown as Record<string, React.ElementType>)[name];

    if (!PhosphorIcon) {
        return (
            <span key="FileText" className="contents" >
                <PhosphorIcons.FileText size={size} className={className} {...props} />
            </span>
        );
    }

    return (
        <span key={name} className="contents" >
            <PhosphorIcon size={size} className={className} {...props} />
        </span>
    );
};

import { Component, type ErrorInfo, type ReactNode } from 'react';
import { Warning, ArrowClockwise, House } from '@phosphor-icons/react';

interface Props {
  children?: ReactNode;
  fallback?: ReactNode;
  onReset?: () => void;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null
  };

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
  }

  private handleReset = () => {
    this.setState({ hasError: false, error: null });
    if (this.props.onReset) {
      this.props.onReset();
    }
  };

  public render() {
    if (this.state.hasError) {
      if (this.props.fallback) {
        return this.props.fallback;
      }

      return (
        <div className="flex flex-col items-center justify-center h-full w-full p-8 text-center bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 rounded-xl" >
          <div className="bg-red-500/10 text-red-500 p-4 rounded-full mb-6" >
            <Warning size={48} weight="duotone" />
          </div>
          <h2 className="mb-4 text-2xl font-bold" >Oups ! Une erreur est survenue.</h2>
          <p className="text-slate-500 dark:text-slate-400 mb-8 max-w-[400px]" >
            L'application a rencontré un problème inattendu. Rassurez-vous, vos données sont sauvegardées.
          </p>

          {this.state.error && (
            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 p-4 rounded-lg text-sm text-red-500 max-w-[600px] overflow-auto text-left mb-8 font-mono" >
              {(this.state.error as Error).message}
            </div>
          )}

          <div className="flex gap-4" >
            <button
              onClick={this.handleReset}
              className="settings-btn secondary flex items-center gap-2"

            >
              <ArrowClockwise size={18} />
              Réessayer
            </button>
            <button
              onClick={() => window.location.reload()}
              className="settings-btn primary flex items-center gap-2"

            >
              <House size={18} />
              Recharger l'application
            </button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

import React, { useEffect, useState, useRef, useCallback } from 'react';
import { useEditor, EditorContent } from '@tiptap/react';
import { BubbleMenu } from '@tiptap/react/menus';
import StarterKit from '@tiptap/starter-kit';
import Highlight from '@tiptap/extension-highlight';
import Placeholder from '@tiptap/extension-placeholder';
import { Table } from '@tiptap/extension-table';
import { TableRow } from '@tiptap/extension-table-row';
import { TableCell } from '@tiptap/extension-table-cell';
import { TableHeader } from '@tiptap/extension-table-header';
import Link from '@tiptap/extension-link';
import Underline from '@tiptap/extension-underline';
import TextAlign from '@tiptap/extension-text-align';
import Image from '@tiptap/extension-image';
import { Color } from '@tiptap/extension-color';
import { TextStyle } from '@tiptap/extension-text-style';
import { Markdown } from 'tiptap-markdown';
import { 
    TextB, TextItalic, TextUnderline, TextAlignLeft, TextAlignCenter, TextAlignRight,
    ListBullets, ListNumbers, TextHOne, TextHTwo, TextHThree, HighlighterCircle, 
    Table as TableIcon, Link as LinkIcon, Image as ImageIcon,
    Info, Warning, GraduationCap, Brain, Cards, ArrowLeft, FloppyDisk, Plus, X, CornersOut, CornersIn, EyeSlash
} from '@phosphor-icons/react';
import type { Card } from '../types';
import { MedicalAlert } from './CourseEditor'; // Reusing the same node!
import { ClozeExtension } from './editor/ClozeExtension';
import { usePromptStore } from '../store/usePromptStore';
import { CardSuggestionPlugin } from './editor/CardSuggestionPlugin';
import { getSuggestionOptions } from './editor/suggestionConfig';

interface FullCourseEditorProps {
    course: Card;
    onSave: (course: Card) => void;
    onCancel: () => void;
    existingCards: Card[];
}

export const FullCourseEditor: React.FC<FullCourseEditorProps> = ({
    course,
    onSave,
    onCancel,
    existingCards
}) => {
    const [title, setTitle] = useState(course.title);
    const [subject, setSubject] = useState(course.subject || '');
    const [tags, setTags] = useState<string[]>(course.tags || []);
    const [tagInput, setTagInput] = useState('');
    const [showCardSelector, setShowCardSelector] = useState(false);
    const [cardSearch, setCardSearch] = useState('');
    const selectorRef = useRef<HTMLDivElement>(null);
    const isExplicitlyClosedRef = useRef(false);
    const editorContainerRef = useRef<HTMLDivElement>(null);
    const [isFullscreen, setIsFullscreen] = useState(false);

    const editor = useEditor({
        editorProps: {
            attributes: {
                class: 'prose dark:prose-invert prose-indigo max-w-none focus:outline-none min-h-full'
            }
        },
        extensions: [
            StarterKit,
            Highlight.configure({ HTMLAttributes: { class: 'bg-yellow-200 dark:bg-yellow-800/50 px-1 rounded' } }),
            Underline,
            TextAlign.configure({ types: ['heading', 'paragraph'] }),
            Image.configure({ inline: true, allowBase64: true }),
            TextStyle,
            Color,
            Placeholder.configure({ placeholder: 'Rédigez le contenu de votre cours ici...' }),
            Table.configure({ resizable: true }),
            TableRow,
            TableHeader,
            TableCell,
            Link.configure({ openOnClick: false }),
            Markdown,
            MedicalAlert, // Same medical blocks
            CardSuggestionPlugin.configure({
                suggestion: getSuggestionOptions(existingCards),
            }),
            ClozeExtension,
        ],
        content: course.details || course.content || '',
    });

    const setLink = useCallback(async () => {
        const previousUrl = editor?.getAttributes('link').href;
        const url = await usePromptStore.getState().openPrompt('URL', previousUrl);
        if (url === null) return;
        if (url === '') {
            editor?.chain().focus().extendMarkRange('link').unsetLink().run();
            return;
        }
        editor?.chain().focus().extendMarkRange('link').setLink({ href: url }).run();
    }, [editor]);

    const addImage = useCallback(async () => {
        const url = await usePromptStore.getState().openPrompt('URL de l\'image');
        if (url) {
            editor?.chain().focus().setImage({ src: url }).run();
        }
    }, [editor]);

    const handleSave = useCallback(() => {
        if (!editor) return;

        // Extract Markdown
        const contentMarkdown = (editor.storage as any).markdown.getMarkdown();

        // Extract a plain text summary for 'content'
        const plainText = editor.getText();
        const snippet = plainText.substring(0, 300) + (plainText.length > 300 ? '...' : '');

        onSave({
            ...course,
            title,
            subject,
            tags,
            content: snippet,
            details: contentMarkdown,
        });
    }, [editor, course, title, subject, tags, onSave]);

    const addTag = () => {
        if (tagInput.trim() && !tags.includes(tagInput.trim())) {
            setTags([...tags, tagInput.trim()]);
            setTagInput('');
        }
    };

    const removeTag = (tagToRemove: string) => {
        setTags(tags.filter(t => t !== tagToRemove));
    };

    const addAlert = (type: string) => {
        editor?.chain().focus().insertContent({
            type: 'medicalAlert',
            attrs: { type },
            content: [{ type: 'paragraph' }]
        }).run();
    };

    const handleSaveRef = useRef(handleSave);
    useEffect(() => {
        handleSaveRef.current = handleSave;
    }, [handleSave]);

    // Auto-save logic
    useEffect(() => {
        // Debounced auto-save directly to onSave
        const timeout = setTimeout(() => {
            if (!isExplicitlyClosedRef.current) {
                handleSaveRef.current();
            }
        }, 1500);
        return () => clearTimeout(timeout);
    }, [handleSave]);

    // Unmount auto-save
    useEffect(() => {
        return () => {
            if (!isExplicitlyClosedRef.current) {
                handleSaveRef.current();
            }
        };
    }, []);

    const toggleFullscreen = useCallback(() => {
        if (!document.fullscreenElement) {
            editorContainerRef.current?.requestFullscreen().catch(err => {
            });
        } else {
            document.exitFullscreen();
        }
    }, []);

    useEffect(() => {
        const handleFullscreenChange = () => {
            setIsFullscreen(!!document.fullscreenElement);
        };
        document.addEventListener('fullscreenchange', handleFullscreenChange);
        return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
    }, []);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if ((e.metaKey || e.ctrlKey) && e.shiftKey && e.key.toLowerCase() === 'f') {
                e.preventDefault();
                toggleFullscreen();
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [toggleFullscreen]);

    const insertCardLink = (card: { id: string; title: string }) => {
        editor?.chain().focus().insertContent(`<a href="card://${card.id}">${card.title}</a> `).run();
        setShowCardSelector(false);
        setCardSearch('');
    };

    // Close selector when clicking outside
    useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            if (selectorRef.current && !selectorRef.current.contains(e.target as globalThis.Node)) {
                setShowCardSelector(false);
            }
        };
        if (showCardSelector) document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [showCardSelector]);

    const filteredCards = existingCards.filter(c => c.title.toLowerCase().includes(cardSearch.toLowerCase())).slice(0, 10);

    if (!editor) return <div className="p-12 text-red-500" >Chargement de l'éditeur... (si ce message reste, c'est que l'éditeur a planté)</div>;

    return (
        <div ref={editorContainerRef} className={`full-course-editor flex flex-col h-full overflow-hidden ${isFullscreen ? 'bg-white dark:bg-slate-900' : 'bg-slate-50 dark:bg-slate-950'}`}>
            <div className="flex-1 overflow-y-auto px-4 py-8 flex justify-center" >
                <div className="w-full max-w-[1200px] bg-white dark:bg-slate-900 rounded-xl shadow-md flex flex-col" >

                    {/* Course Meta (Title, Tags) */}
                    <div className="p-6 pb-4 border-b border-slate-50 dark:border-slate-950" >
                        <div className="flex items-center justify-between mb-6" >
                            <button onClick={() => {
                                isExplicitlyClosedRef.current = true;
                                handleSave(); // Save one last time before leaving
                                onCancel();
                            }} className="inline-flex items-center gap-2 bg-transparent border-none text-slate-500 font-semibold px-3 py-1.5 rounded-lg -ml-3 cursor-pointer transition-colors duration-150" 


                            >
                                <ArrowLeft size={18} weight="bold" />
                                Retour
                            </button>

                            <span className="text-xs text-slate-500" >
                                (Sauvegarde auto activée)
                            </span>

                            <div className="flex gap-2" >
                                <button onClick={toggleFullscreen} className="inline-flex items-center gap-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-slate-100 font-semibold px-3 py-1.5 rounded-lg cursor-pointer transition-colors duration-150" 


                                title="Mode Focus (Cmd+Shift+F)"
                                >
                                    {isFullscreen ? <CornersIn size={18} weight="bold" /> : <CornersOut size={18} weight="bold" />}
                                    <span className={isFullscreen ? 'hidden' : 'inline'}>Focus</span>
                                </button>
                                <button onClick={() => {
                                    handleSave();
                                }} className="inline-flex items-center gap-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-slate-100 font-semibold px-3 py-1.5 rounded-lg cursor-pointer transition-colors duration-150 -mr-3" 


                                >
                                    <FloppyDisk size={18} weight="bold" />
                                    Enregistrer
                                </button>
                            </div>
                        </div>

                        <input 
                            type="text"
                            value={title}
                            onChange={(e) => setTitle(e.target.value)}
                            placeholder="Titre du cours..."
                            className="w-full border-none outline-none text-4xl font-extrabold text-slate-900 dark:text-slate-100 mb-4 bg-transparent" 
                        />
                        <div className="flex gap-4 flex-wrap" >
                            <div className="flex items-center gap-2 flex-1 basis-[250px]" >
                                <span className="color-slate-500 text-sm font-medium" >Matière:</span>
                                <input 
                                    type="text"
                                    value={subject}
                                    onChange={(e) => setSubject(e.target.value)}
                                    placeholder="Ex: Cardiologie..."
                                    className="flex-1 min-w-[150px] border-none outline-none text-sm text-slate-900 dark:text-slate-100 bg-slate-50 dark:bg-slate-950 px-3 py-1.5 rounded-md" 
                                />
                            </div>
                            <div className="flex items-start gap-2 flex-1 basis-[300px] flex-col" >
                                <span className="color-slate-500 text-sm font-medium" >Tags:</span>
                                <div className="flex flex-wrap gap-1.5 items-center" >
                                    {tags.map(tag => (
                                        <span key={tag} className="inline-flex items-center gap-1 bg-slate-50 dark:bg-slate-950 px-2.5 py-1 rounded-full text-[0.85rem] text-slate-900 dark:text-slate-100 border border-slate-200 dark:border-slate-700" >
                                            #{tag}
                                            <X size={12} weight="bold" className="cursor-pointer text-slate-500 hover:text-red-500 transition-colors"  onClick={() => removeTag(tag)}   />
                                        </span>
                                    ))}
                                    <div className="flex items-center gap-1.5 bg-slate-50 dark:bg-slate-950 px-3 py-1 rounded-full border border-slate-200 dark:border-slate-700" >
                                        <Plus size={14} className="cursor-pointer text-slate-500 hover:text-slate-900 dark:hover:text-slate-100"  onClick={addTag} />
                                        <input 
                                            type="text"
                                            value={tagInput}
                                            onChange={(e) => setTagInput(e.target.value)}
                                            onKeyDown={(e) => e.key === 'Enter' && addTag()}
                                            placeholder="Nouveau tag..."
                                            className="border-none outline-none text-[0.85rem] text-slate-900 dark:text-slate-100 bg-transparent w-[100px]" 
                                        />
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Toolbar */}
                    <div className="course-editor-toolbar px-6 py-3 border-b border-slate-200 dark:border-slate-700 flex flex-wrap bg-white dark:bg-slate-900 sticky top-0 z-10" >
                        <button type="button" onClick={() => editor.chain().focus().toggleBold().run()} className={`toolbar-btn ${editor.isActive('bold') ? 'is-active' : ''}`} title="Gras">
                            <TextB size={18} />
                        </button>
                        <button type="button" onClick={() => editor.chain().focus().toggleItalic().run()} className={`toolbar-btn ${editor.isActive('italic') ? 'is-active' : ''}`} title="Italique">
                            <TextItalic size={18} />
                        </button>
                        <button type="button" onClick={() => editor.chain().focus().toggleUnderline().run()} className={`toolbar-btn ${editor.isActive('underline') ? 'is-active' : ''}`} title="Souligné">
                            <TextUnderline size={18} />
                        </button>
                        <button type="button" onClick={() => editor.chain().focus().toggleHighlight().run()} className={`toolbar-btn ${editor.isActive('highlight') ? 'is-active' : ''}`} title="Surligner">
                            <HighlighterCircle size={18} />
                        </button>
                        <button type="button" onClick={() => editor.chain().focus().toggleCloze().run()} className={`toolbar-btn ${editor.isActive('cloze') ? 'is-active' : ''}`} title="Texte à trou (Cmd+E)">
                            <EyeSlash size={18} />
                        </button>
                        <input 
                            type="color" 
                            onInput={(event) => editor.chain().focus().setColor((event.target as HTMLInputElement).value).run()}
                            value={editor.getAttributes('textStyle').color || 'var(--color-text)'}
                            className="w-7 h-7 p-0 border-none rounded cursor-pointer ml-1" 
                            title="Couleur du texte"
                        />

                        <div className="toolbar-divider" />

                        <button type="button" onClick={() => editor.chain().focus().setTextAlign('left').run()} className={`toolbar-btn ${editor.isActive({ textAlign: 'left' }) ? 'is-active' : ''}`} title="Aligner à gauche">
                            <TextAlignLeft size={18} />
                        </button>
                        <button type="button" onClick={() => editor.chain().focus().setTextAlign('center').run()} className={`toolbar-btn ${editor.isActive({ textAlign: 'center' }) ? 'is-active' : ''}`} title="Centrer">
                            <TextAlignCenter size={18} />
                        </button>
                        <button type="button" onClick={() => editor.chain().focus().setTextAlign('right').run()} className={`toolbar-btn ${editor.isActive({ textAlign: 'right' }) ? 'is-active' : ''}`} title="Aligner à droite">
                            <TextAlignRight size={18} />
                        </button>

                        <div className="toolbar-divider" />

                        <button type="button" onClick={() => editor.chain().focus().toggleHeading({ level: 1 }).run()} className={`toolbar-btn ${editor.isActive('heading', { level: 1 }) ? 'is-active' : ''}`} title="Titre 1">
                            <TextHOne size={18} />
                        </button>
                        <button type="button" onClick={() => editor.chain().focus().toggleHeading({ level: 2 }).run()} className={`toolbar-btn ${editor.isActive('heading', { level: 2 }) ? 'is-active' : ''}`} title="Titre 2">
                            <TextHTwo size={18} />
                        </button>
                        <button type="button" onClick={() => editor.chain().focus().toggleHeading({ level: 3 }).run()} className={`toolbar-btn ${editor.isActive('heading', { level: 3 }) ? 'is-active' : ''}`} title="Titre 3">
                            <TextHThree size={18} />
                        </button>

                        <div className="toolbar-divider" />

                        <button type="button" onClick={() => editor.chain().focus().toggleBulletList().run()} className={`toolbar-btn ${editor.isActive('bulletList') ? 'is-active' : ''}`} title="Liste à puces">
                            <ListBullets size={18} />
                        </button>
                        <button type="button" onClick={() => editor.chain().focus().toggleOrderedList().run()} className={`toolbar-btn ${editor.isActive('orderedList') ? 'is-active' : ''}`} title="Liste numérotée">
                            <ListNumbers size={18} />
                        </button>

                        <div className="toolbar-divider" />

                        <button type="button" onClick={setLink} className={`toolbar-btn ${editor.isActive('link') ? 'is-active' : ''}`} title="Lien">
                            <LinkIcon size={18} />
                        </button>
                        <button type="button" onClick={addImage} className="toolbar-btn" title="Image">
                            <ImageIcon size={18} />
                        </button>
                        <button type="button" onClick={() => editor.chain().focus().insertTable({ rows: 3, cols: 3, withHeaderRow: true }).run()} className="toolbar-btn" title="Insérer un tableau">
                            <TableIcon size={18} />
                        </button>
                        <button type="button" onClick={() => setShowCardSelector(!showCardSelector)} className="toolbar-btn relative" title="Lier une carte existante" >
                            <Cards size={18} />
                        </button>

                        <div className="toolbar-divider" />

                        {/* Blocs Médicaux Spécifiques */}
                        <button type="button" onClick={() => addAlert('definition')} className="toolbar-btn text-blue-600 dark:text-blue-500"  title="Définition">
                            <Info size={18} weight="bold" /> <span className="text-xs ml-1 font-semibold" >Déf.</span>
                        </button>
                        <button type="button" onClick={() => addAlert('concours')} className="toolbar-btn text-amber-600 dark:text-amber-500"  title="À connaître (Concours)">
                            <GraduationCap size={18} weight="bold" /> <span className="text-xs ml-1 font-semibold" >Concours</span>
                        </button>
                        <button type="button" onClick={() => addAlert('vigilance')} className="toolbar-btn text-red-600 dark:text-red-500"  title="Vigilance">
                            <Warning size={18} weight="bold" /> <span className="text-xs ml-1 font-semibold" >Vigi.</span>
                        </button>
                        <button type="button" onClick={() => addAlert('expert')} className="toolbar-btn text-slate-900 dark:text-slate-100"  title="Expert">
                            <Brain size={18} weight="bold" /> <span className="text-xs ml-1 font-semibold" >Expert</span>
                        </button>
                    </div>

                    {showCardSelector && (
                        <div ref={selectorRef} className="card-selector-popup absolute top-[230px] left-1/2 -translate-x-1/2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg p-2 z-50 shadow-md w-[300px] flex flex-col gap-2" >
                            <input 
                                type="text" 
                                autoFocus
                                placeholder="Rechercher une carte..." 
                                value={cardSearch}
                                onChange={(e) => setCardSearch(e.target.value)}
                                className="px-2 py-1.5 border border-slate-200 dark:border-slate-700 rounded outline-none bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100" 
                            />
                            <div className="max-h-[200px] overflow-y-auto flex flex-col" >
                                {filteredCards.length > 0 ? filteredCards.map(c => (
                                    <button 
                                        key={c.id} 
                                        type="button" 
                                        onClick={() => insertCardLink(c)}
                                        className="px-2 py-1.5 text-left bg-transparent border-none rounded cursor-pointer text-sm text-slate-900 dark:text-slate-100 transition-colors" 
                                        onMouseOver={(e) => e.currentTarget.style.background = 'var(--color-bg)'}
                                        onMouseOut={(e) => e.currentTarget.style.background = 'transparent'}
                                        onFocus={(e) => e.currentTarget.style.background = 'var(--color-bg)'}
                                        onBlur={(e) => e.currentTarget.style.background = 'transparent'}
                                    >
                                        {c.title}
                                    </button>
                                )) : <div className="p-2 text-sm text-slate-500 text-center" >Aucune carte trouvée</div>}
                            </div>
                        </div>
                    )}

                    {editor && (
                        <BubbleMenu editor={editor} className="course-editor-toolbar bubble-menu p-2 border border-slate-200 dark:border-slate-700 rounded-lg bg-white dark:bg-slate-900 shadow-md" >
                            <button type="button" onClick={() => editor.chain().focus().toggleBold().run()} className={`toolbar-btn ${editor.isActive('bold') ? 'is-active' : ''}`} title="Gras">
                                <TextB size={18} />
                            </button>
                            <button type="button" onClick={() => editor.chain().focus().toggleItalic().run()} className={`toolbar-btn ${editor.isActive('italic') ? 'is-active' : ''}`} title="Italique">
                                <TextItalic size={18} />
                            </button>
                            <button type="button" onClick={() => editor.chain().focus().toggleUnderline().run()} className={`toolbar-btn ${editor.isActive('underline') ? 'is-active' : ''}`} title="Souligné">
                                <TextUnderline size={18} />
                            </button>
                            <button type="button" onClick={() => editor.chain().focus().toggleHighlight().run()} className={`toolbar-btn ${editor.isActive('highlight') ? 'is-active' : ''}`} title="Surligner">
                                <HighlighterCircle size={18} />
                            </button>
                            <button type="button" onClick={() => editor.chain().focus().toggleCloze().run()} className={`toolbar-btn ${editor.isActive('cloze') ? 'is-active' : ''}`} title="Texte à trou (Cmd+E)">
                                <EyeSlash size={18} />
                            </button>
                            <button type="button" onClick={setLink} className={`toolbar-btn ${editor.isActive('link') ? 'is-active' : ''}`} title="Lien">
                                <LinkIcon size={18} />
                            </button>
                        </BubbleMenu>
                    )}

                    {/* Editor Content Area */}
                    <div className="course-editor-content px-12 py-4 pb-16 flex-1 overflow-visible min-h-[500px]" >
                        <EditorContent editor={editor} />
                    </div>
                </div>
            </div>
        </div>
    );
};

