import React from 'react';

import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import remarkMath from 'remark-math';
import rehypeKatex from 'rehype-katex';
import rehypeRaw from 'rehype-raw';
import rehypeSanitize, { defaultSchema } from 'rehype-sanitize';
import 'katex/dist/katex.min.css';
import { InteractiveCardLink } from './ui/InteractiveCardLink';

interface MarkdownRendererProps {
    content: string;
    className?: string;
    onInternalLinkClick?: (target: string) => void;
}

// Helper to process children for Cloze Deletion (||text||)
const renderWithCloze = (children: React.ReactNode): React.ReactNode => {
    return React.Children.map(children, child => {
        if (typeof child === 'string') {
            const parts = child.split(/\|\|(.*?)\|\|/g);
            if (parts.length === 1) return child; // No matches

            return parts.map((part, index) => {
                // Even indices are normal text, odd are cloze
                if (index % 2 === 1) {
                    return <span key={index} className="cloze-spoiler">{part}</span>;
                }
                return part;
            });
        }
        return child;
    });
};

export const MarkdownRenderer: React.FC<MarkdownRendererProps> = ({ content, className = '', onInternalLinkClick }) => {
    // Pre-process content to handle custom line breaks using '\'
    // We replace '\' that is NOT preceded by '\' (to avoid \\) and NOT followed by a non-whitespace (to protect \frac, etc.)
    // with '  \n' which ensures a hard break in Markdown.
    const processedContent = React.useMemo(() => {
        if (!content) return '';
        let processed = content;

        // Handle custom line breaks using '\'
        processed = processed.replace(/(?<!\\)\\(?=\s|$)/g, '  \n');
        // Handle highlight syntax: ==text== -> <mark>text</mark>
        processed = processed.replace(/==([^=]+)==/g, '<mark>$1</mark>');
        // Handle wiki links: [[text]] -> <a href="#internal:text" class="wiki-link">text</a>
        processed = processed.replace(/\[\[(.*?)\]\]/g, '<a href="#internal:$1" class="wiki-link">$1</a>');
        return processed;
    }, [content]);

    return (
        <div className={`prose dark:prose-invert prose-indigo max-w-none ${className}`}>
            <ReactMarkdown
                remarkPlugins={[remarkGfm, remarkMath]}
                rehypePlugins={[
                    rehypeRaw, 
                    [rehypeSanitize, {
                        ...defaultSchema,
                        attributes: {
                            ...defaultSchema.attributes,
                            // Ensure class names and specific attributes are kept
                            '*': [...(defaultSchema.attributes?.['*'] || []), 'className', 'style'],
                            a: [...(defaultSchema.attributes?.a || []), 'target', 'rel'],
                            // Support for mark tags
                            mark: ['className'],
                        },
                        // Explicitly deny scripts and event handlers (already default, but good practice to assert)
                        tagNames: defaultSchema.tagNames?.filter(t => t !== 'script' && t !== 'style' && t !== 'iframe'),
                    }], 
                    rehypeKatex
                ]}
                components={{
                    // Cloze Deletion Support
                    p: ({ node, children, ...props }) => (
                        <p {...props}>{renderWithCloze(children)}</p>
                    ),
                    li: ({ node, children, ...props }) => (
                        <li {...props}>{renderWithCloze(children)}</li>
                    ),

                    // Style mark tags (highlights)
                    mark: ({ node, ...props }) => (
                        <mark {...props} className="bg-yellow-200/60 dark:bg-yellow-500/30 text-inherit px-1 rounded-sm" />
                    ),
                    // Customize link rendering
                    a: ({ node, href, ...props }) => {
                        if (href?.startsWith('#internal:')) {
                            const target = decodeURIComponent(href.replace('#internal:', ''));
                            return (
                                <InteractiveCardLink 
                                    target={target}
                                    onClick={onInternalLinkClick}
                                >
                                    {props.children}
                                </InteractiveCardLink>
                            );
                        }
                        return <a {...props} href={href} target="_blank" rel="noopener noreferrer" />;
                    },
                    // Style blockquotes and alerts
                    blockquote: ({ node, children, ...props }) => {
                        // Check for GitHub-style alerts
                        const firstChild = React.Children.toArray(children)[0];

                        // Check if first child is an element and has children
                        if (React.isValidElement(firstChild)) {
                            const element = firstChild as React.ReactElement<{ children?: React.ReactNode }>;
                            if (element.props.children) {
                                const text = String(Array.isArray(element.props.children)
                                    ? (element.props.children as unknown[])[0]
                                    : element.props.children || '');

                                if (text.startsWith('[!NOTE]')) {
                                    return (
                                        <div className="not-prose my-4 p-4 bg-blue-50 dark:bg-blue-900/20 border-l-4 border-blue-500 rounded-r-lg text-blue-900 dark:text-blue-100">
                                            <div className="font-semibold mb-1 text-blue-700 dark:text-blue-400 flex items-center gap-2">ℹ️ Note</div>
                                            <div className="text-sm opacity-90">{children}</div>
                                        </div>
                                    );
                                }
                                if (text.startsWith('[!TIP]')) {
                                    return (
                                        <div className="not-prose my-4 p-4 bg-green-50 dark:bg-green-900/20 border-l-4 border-green-500 rounded-r-lg text-green-900 dark:text-green-100">
                                            <div className="font-semibold mb-1 text-green-700 dark:text-green-400 flex items-center gap-2">💡 Astuce</div>
                                            <div className="text-sm opacity-90">{children}</div>
                                        </div>
                                    );
                                }
                                if (text.startsWith('[!IMPORTANT]')) {
                                    return (
                                        <div className="not-prose my-4 p-4 bg-purple-50 dark:bg-purple-900/20 border-l-4 border-purple-500 rounded-r-lg text-purple-900 dark:text-purple-100">
                                            <div className="font-semibold mb-1 text-purple-700 dark:text-purple-400 flex items-center gap-2">📢 Important</div>
                                            <div className="text-sm opacity-90">{children}</div>
                                        </div>
                                    );
                                }
                                if (text.startsWith('[!WARNING]')) {
                                    return (
                                        <div className="not-prose my-4 p-4 bg-amber-50 dark:bg-amber-900/20 border-l-4 border-amber-500 rounded-r-lg text-amber-900 dark:text-amber-100">
                                            <div className="font-semibold mb-1 text-amber-700 dark:text-amber-400 flex items-center gap-2">⚠️ Attention</div>
                                            <div className="text-sm opacity-90">{children}</div>
                                        </div>
                                    );
                                }
                                if (text.startsWith('[!CAUTION]')) {
                                    return (
                                        <div className="not-prose my-4 p-4 bg-red-50 dark:bg-red-900/20 border-l-4 border-red-500 rounded-r-lg text-red-900 dark:text-red-100">
                                            <div className="font-semibold mb-1 text-red-700 dark:text-red-400 flex items-center gap-2">🛑 Danger</div>
                                            <div className="text-sm opacity-90">{children}</div>
                                        </div>
                                    );
                                }
                            }
                        }

                        // Default blockquote handled by prose
                        return (
                            <blockquote {...props}>
                                {children}
                            </blockquote>
                        );
                    },
                }}
            >
                {processedContent}
            </ReactMarkdown>
        </div>
    );
};

import React from 'react';
import { Brain, Link as LinkIcon, ArrowsLeftRight, Hand, Trash, ArrowsMerge } from '@phosphor-icons/react';

interface NetworkTooltipProps {
    link: Record<string, unknown>; // Using Record for Link object as seen in NetworkView usage
    onReportIncorrect?: () => void;
}

export const NetworkTooltip: React.FC<NetworkTooltipProps> = ({ link, onReportIncorrect }) => {
    // 1. Determine Type & Style
    const getTypeDetails = (type: string) => {
        switch (type) {
            case 'explicit':
                return { label: 'Référence', className: 'bg-gradient-to-br from-indigo-500/15 to-indigo-500/5 text-indigo-600 dark:text-indigo-300 border border-indigo-500/20', icon: LinkIcon };
            case 'hybrid':
                return { label: 'Hybride', className: 'bg-gradient-to-br from-cyan-500/15 to-cyan-500/5 text-cyan-600 dark:text-cyan-300 border border-cyan-500/20', icon: ArrowsMerge };
            case 'manual':
                return { label: 'Manuel', className: 'bg-gradient-to-br from-amber-500/15 to-amber-500/5 text-amber-600 dark:text-amber-300 border border-amber-500/20', icon: Hand };
            case 'semantic':
            default:
                return { label: 'Sémantique', className: 'bg-gradient-to-br from-purple-500/15 to-purple-500/5 text-purple-600 dark:text-purple-300 border border-purple-500/20', icon: Brain };
        }
    };

    const typeDetails = getTypeDetails((link.type as string) || 'semantic');
    const TypeIcon = typeDetails.icon;

    // 2. Score Calculation
    const score = Math.round(((link.value as number) || 0) * 100);

    // Color scale for progress bar
    const getScoreColor = (s: number) => {
        if (s >= 80) return 'linear-gradient(90deg, #10b981, #34d399)'; // Emerald
        if (s >= 50) return 'linear-gradient(90deg, #f59e0b, #fbbf24)'; // Amber
        return 'linear-gradient(90deg, #ef4444, #f87171)'; // Red
    };

    const sourceName = typeof link.source === 'object' ? (link.source as any).name : link.source;
    const targetName = typeof link.target === 'object' ? (link.target as any).name : link.target;

    return (
        <div className="w-max min-w-[280px] max-w-[450px] pointer-events-auto animate-in fade-in zoom-in-95 duration-200">
            <div className="bg-white dark:bg-slate-900/80 dark:backdrop-blur-md rounded-2xl overflow-hidden shadow-2xl border border-slate-200 dark:border-slate-800">
                <div className="flex flex-col px-4 py-3">

                    {/* Header: Type and Action */}
                    <div className="flex items-center justify-between mb-2">
                        <div className={`inline-flex items-center gap-1 text-[10px] font-extrabold uppercase tracking-wider px-2 py-[3px] rounded-lg ${typeDetails.className}`}>
                            <TypeIcon size={12} weight="bold" />
                            <span>{typeDetails.label}</span>
                        </div>
                        {onReportIncorrect && (
                            <button 
                                onClick={onReportIncorrect}
                                className="text-slate-400 hover:text-red-500 transition-colors p-1 rounded-md hover:bg-red-50 dark:hover:bg-red-900/20"
                                title="Signaler ce lien comme incorrect"
                            >
                                <Trash size={14} weight="fill" />
                            </button>
                        )}
                    </div>

                    {/* Nodes relationship */}
                    <div className="flex items-center justify-between gap-4 py-2 text-[15px] font-bold">
                        <span className="text-slate-800 dark:text-slate-100 text-right leading-tight break-words text-sm flex-[0_1_auto]" title={sourceName}>{sourceName}</span>
                        <div className="shrink-0 flex items-center justify-center w-5 h-5 rounded-full bg-slate-100 dark:bg-slate-800">
                            <ArrowsLeftRight size={12} className="text-slate-400 dark:text-slate-500" weight="bold" />
                        </div>
                        <span className="text-slate-800 dark:text-slate-100 text-left leading-tight break-words text-sm flex-[0_1_auto]" title={targetName}>{targetName}</span>
                    </div>

                    {/* Confidence Score */}
                    <div className="mt-3 bg-slate-50 dark:bg-slate-800/40 rounded-lg p-2 border border-slate-100 dark:border-slate-700/50">
                        <div className="flex items-center justify-between mb-3">
                            <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Force du lien</span>
                            <span className="text-[11px] font-black text-slate-700 dark:text-slate-300">{score}%</span>
                        </div>
                        <div className="w-full h-1.5 rounded-full bg-slate-200 dark:bg-slate-700 overflow-hidden shadow-inner">
                            <div 
                                className="h-full rounded-full transition-all duration-700 ease-out"
                                style={{ width: `${score}%`, background: getScoreColor(score) }}
                            />
                        </div>
                    </div>

                </div>
            </div>
        </div>
    );
};

