                            </div>
                        </section>

                        {/* Main Charts */}
                        <section className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                            {/* Forecast Chart */}
                            <div className="bg-white dark:bg-slate-900 border border-slate-200/60 dark:border-slate-800 rounded-3xl p-6 shadow-sm flex flex-col h-[350px]">
