                            if (url === '') {
                                editor.chain().focus().extendMarkRange('link').unsetLink().run();
                                return;
                            }
                            editor.chain().focus().extendMarkRange('link').setLink({ href: url }).run();
                        }}
                        className={`p-1.5 rounded-lg transition-all ${editor.isActive('link') ? 'bg-slate-200 dark:bg-slate-800 text-slate-900 dark:text-white' : 'hover:bg-white dark:hover:bg-slate-800 hover:shadow-sm hover:text-slate-800 dark:hover:text-white'}`}
                    >
                        <LinkIcon size={16} />
                    </button>
                </div>
            </div>
        </div>
    );
};

export const TipTapEditor: React.FC<TipTapEditorProps> = ({ value, onChange, placeholder = "Commencez à écrire ici..." }) => {

    const lastValueRef = useRef(value);

    const editor = useEditor({
        extensions: [
            StarterKit,
            Underline,
            Link.configure({
                openOnClick: false,
            }),
            Placeholder.configure({
                placeholder,
                emptyEditorClass: 'is-editor-empty',
            }),
            ClozeExtension,
            Markdown.configure({
                html: false,
                tightLists: true,
                tightListClass: 'tight',
                bulletListMarker: '-',
                linkify: true,
                breaks: true,
            }),
        ],
        content: value,
        onUpdate: ({ editor }) => {
            // Retrieve markdown
            const markdown = (editor.storage as any).markdown.getMarkdown();
            lastValueRef.current = markdown;
            onChange(markdown);
        },
        editorProps: {
            attributes: {
                class: 'prose dark:prose-invert prose-slate prose-lg max-w-none focus:outline-none min-h-[300px]',
            },
        },
    });

    // Handle incoming value changes (e.g. if cleared from outside)
    useEffect(() => {
        if (editor && value !== lastValueRef.current) {
            lastValueRef.current = value;
            editor.commands.setContent(value);
        }
    }, [value, editor]);

    return (
        <div className="flex-1 w-full flex flex-col tiptap-wrapper">
            <MenuBar editor={editor} />
            <EditorContent editor={editor} className="flex-1 w-full cursor-text" onClick={() => editor?.commands.focus()} />
        </div>
    );
};

import { ReactRenderer } from '@tiptap/react';
import { SuggestionList } from './SuggestionList';
import type { Card } from '../../types';

export const getSuggestionOptions = (cards: Card[]) => ({
  char: '[[',
  items: ({ query }: { query: string }) => {
    return cards
      .filter((item) => item.title.toLowerCase().includes(query.toLowerCase()))
      .slice(0, 5); // Limit to 5 results
  },
  render: () => {
    let component: ReactRenderer<any>;

    return {
      onStart: (props: any) => {
        // Render the React component and pass the props
        component = new ReactRenderer(SuggestionList, {
          props,
          editor: props.editor,
        });

        // The component handles rendering itself since we pass clientRect
      },
      onUpdate(props: any) {
        component.updateProps(props);
      },
      onKeyDown(props: any) {
        if (props.event.key === 'Escape') {
          return true; // We can handle escape here if needed
        }
        return component.ref?.onKeyDown(props);
      },
      onExit() {
        if (component) {
          component.destroy();
        }
      },
    };
  },
});

