import React, { useState, useEffect } from 'react';
import { Brain, Lightning, ShieldWarning, Trash } from '@phosphor-icons/react';
import { getDashboardStats, resetFeedback, type DashboardStats } from '../../linkFeedback';
import { SettingsCard, CardSection, CardBody, StatCard, DangerButton } from './SettingsUI';

export const IntelligenceTab: React.FC = () => {
    const [dashStats, setDashStats] = useState<DashboardStats | null>(null);

    useEffect(() => {
        setDashStats(getDashboardStats());
    }, []);

    if (!dashStats) return null;

    const score = dashStats.learningScore;
    const scoreColorHex = score >= 75 ? '#10b981' : score >= 40 ? '#f59e0b' : '#ef4444';
    const scoreColorClass = score >= 75 ? 'text-emerald-500' : score >= 40 ? 'text-amber-500' : 'text-red-500';

    return (
        <div className="flex flex-col gap-6">
            {/* Score card */}
            <SettingsCard>
                <CardBody className="flex flex-col sm:flex-row items-center gap-6">
                    {/* Circle gauge */}
                    <div className="relative flex items-center justify-center shrink-0">
                        <svg width="88" height="88" viewBox="0 0 88 88" fill="none" className="transform -rotate-90">
                            <circle cx="44" cy="44" r="36" className="stroke-slate-200 dark:stroke-slate-700" strokeWidth="8" fill="none" />
                            <circle
                                cx="44" cy="44" r="36"
                                stroke={scoreColorHex}
                                strokeWidth="8"
                                fill="none"
                                strokeDasharray={`${2 * Math.PI * 36}`}
                                strokeDashoffset={`${2 * Math.PI * 36 * (1 - score / 100)}`}
                                strokeLinecap="round"
                                className="transition-all duration-1000 ease-out" 
                            />
                        </svg>
                        <div className="absolute inset-0 flex flex-col items-center justify-center">
                            <span className={`text-2xl font-black tracking-tight leading-none ${scoreColorClass}`}>{score}</span>
                            <span className="text-[10px] font-bold text-slate-400 dark:text-slate-500">/100</span>
                        </div>
                    </div>
                    <div className="text-center sm:text-left">
                        <div className="text-lg font-bold text-slate-900 dark:text-slate-100 mb-1">Score d'apprentissage</div>
                        <div className="text-sm text-slate-500 dark:text-slate-400 leading-relaxed max-w-md">
                            Évaluation de la qualité de l'algorithme de liens sémantiques basée sur vos retours.
                        </div>
                    </div>
                </CardBody>
            </SettingsCard>

            {/* KPI grid */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <StatCard label="Liens générés" value={dashStats.totalLinksGenerated} color="#a855f7" />
                <StatCard label="Supprimés" value={dashStats.totalSuppressed} color="#ef4444" />
                <StatCard label="Manuels" value={dashStats.totalManual} color="#10b981" />
                <StatCard label="Taux d'acceptation" value={`${dashStats.acceptanceRate}%`} color="#8b5cf6" />
            </div>

            {/* Patterns + type-pair */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <SettingsCard>
                    <CardSection title="Patterns appris" icon={<Brain size={18} weight="duotone" />} />
                    <CardBody className="flex flex-col">
                        {[
                            { label: 'Positifs (boosts)', value: dashStats.positivePatternCount, color: 'text-emerald-500', bg: 'bg-emerald-50 dark:bg-emerald-500/10' },
                            { label: 'Négatifs (pénalités)', value: dashStats.negativePatternCount, color: 'text-red-500', bg: 'bg-red-50 dark:bg-red-500/10' },
                            { label: 'Vetos (hard)', value: dashStats.vetoCount, color: 'text-amber-500', bg: 'bg-amber-50 dark:bg-amber-500/10' },
                        ].map((row, i, arr) => (
                            <div key={row.label} className={`flex items-center justify-between py-3.5 ${i < arr.length - 1 ? 'border-b border-slate-200 dark:border-slate-700' : ''}`}>
                                <span className="text-sm font-semibold text-slate-600 dark:text-slate-400">{row.label}</span>
                                <span className={`text-sm font-bold px-2.5 py-0.5 rounded-md ${row.bg} ${row.color}`}>{row.value}</span>
                            </div>
                        ))}
                    </CardBody>
                </SettingsCard>

                <SettingsCard>
                    <CardSection title="Scores type-pair" icon={<Lightning size={18} weight="duotone" />} />
                    <CardBody>
                        {Object.entries(dashStats.typePairScores).length === 0 ? (
                            <div className="text-sm text-slate-500 dark:text-slate-400 py-4 text-center">
                                Aucune donnée enregistrée pour l'instant.
                            </div>
                        ) : (
                            <div className="flex flex-col gap-2">
                                {Object.entries(dashStats.typePairScores).map(([pair, s]) => (
                                    <div key={pair} className="flex items-center justify-between text-sm py-1.5 px-3 rounded-lg bg-slate-50 dark:bg-slate-800/50">
                                        <span className="font-mono text-slate-500 dark:text-slate-400 text-xs">{pair.replace('|', ' ↔ ')}</span>
                                        <span className={`font-bold ${s > 0 ? 'text-emerald-500' : s < 0 ? 'text-red-500' : 'text-slate-400'}`}>
                                            {s > 0 ? '+' : ''}{(s * 100).toFixed(0)}%
                                        </span>
                                    </div>
                                ))}
                            </div>
                        )}
                    </CardBody>
                </SettingsCard>
            </div>

            {/* Toxic keywords */}
            {dashStats.topToxicKeywords.length > 0 && (
                <SettingsCard>
                    <CardSection title="Mots-clés toxiques" subtitle="Ces termes génèrent souvent des faux positifs et sont automatiquement pénalisés." icon={<ShieldWarning size={18} weight="duotone" />} />
                    <CardBody>
                        <div className="flex flex-wrap gap-2.5">
                            {dashStats.topToxicKeywords.map(tw => {
                                const isHigh = tw.count >= 3;
                                return (
                                    <span key={tw.word} className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-wider border ${
                                        isHigh ? 'border-red-200 dark:border-red-900/50 bg-red-50 dark:bg-red-500/10 text-red-600 dark:text-red-400' 
                                               : 'border-amber-200 dark:border-amber-900/50 bg-amber-50 dark:bg-amber-500/10 text-amber-600 dark:text-amber-400'
                                    }`}>
                                        {tw.word} <span className="opacity-70 font-mono tracking-normal">×{tw.count}</span>
                                    </span>
                                );
                            })}
                        </div>
                    </CardBody>
                </SettingsCard>
            )}

            {/* Reset */}
            <SettingsCard danger>
                <CardBody className="flex flex-col sm:flex-row items-center justify-between gap-6 p-6">
                    <div className="flex items-center gap-4 text-center sm:text-left">
                        <div className="w-12 h-12 rounded-full bg-red-50 dark:bg-red-500/10 text-red-500 flex items-center justify-center shrink-0">
                            <Trash size={24} weight="duotone" />
                        </div>
                        <div>
                            <div className="text-base font-bold text-slate-900 dark:text-slate-100 mb-1">Réinitialiser l'intelligence</div>
                            <div className="text-sm text-slate-500 dark:text-slate-400 max-w-md">
                                Supprime tous les patterns, vetos et mots toxiques appris. L'algorithme repartira de zéro.
                            </div>
                        </div>
                    </div>
                    <DangerButton onClick={() => {
                        if (confirm("Réinitialiser toute l'intelligence apprise ?")) {
                            resetFeedback();
                            setDashStats(getDashboardStats());
                        }
                    }} className="w-full sm:w-auto">
                        Réinitialiser
                    </DangerButton>
                </CardBody>
            </SettingsCard>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { ToggleSwitch } from '../ui/ToggleSwitch';
import { isExamModeActive, EXAM_MODE_WINDOW_DAYS } from '../../algorithms/srs';
import { clearSrsSettingsCache } from '../../algorithms/fsrs';
import { loadSettingAsync, loadSettingSync, saveSettingAsync } from '../../persistentSettings';
import { SettingsCard, CardSection, CardBody, SettingsRow, FieldLabel } from './SettingsUI';

export const SRS_SETTINGS_KEY = 'pharmabrain_srs_settings';

export interface SrsSettings {
    examModeEnabled: boolean;
    examDate: string;
    showEasyButton: boolean;
    autoFullscreen: boolean;
    maxNewCardsPerSession: number;
}

export function loadSrsSettings(): SrsSettings {
    return loadSettingSync<SrsSettings>(SRS_SETTINGS_KEY, {
        examModeEnabled: false,
        examDate: new Date().toISOString().split('T')[0],
        showEasyButton: false,
        autoFullscreen: false,
        maxNewCardsPerSession: 10,
    });
}

export function saveSrsSettings(settings: SrsSettings): void {
    saveSettingAsync(SRS_SETTINGS_KEY, settings);
    clearSrsSettingsCache();
}

export const RevisionTab: React.FC = () => {
    const [srsSettings, setSrsSettings] = useState<SrsSettings>(() => loadSrsSettings());

    useEffect(() => {
        loadSettingAsync<SrsSettings>(SRS_SETTINGS_KEY, { examModeEnabled: false, examDate: '', showEasyButton: false, autoFullscreen: false, maxNewCardsPerSession: 10 }).then(setSrsSettings);
    }, []);

    const handleChange = (patch: Partial<SrsSettings>) => {
        const updated = { ...srsSettings, ...patch };
        setSrsSettings(updated);
        saveSrsSettings(updated);
    };

    const examActive = isExamModeActive({
        learningSteps: [1, 10],
        defaultEaseFactor: 2.5,
        minEaseFactor: 1.3,
        fuzzEnabled: true,
        examModeEnabled: srsSettings.examModeEnabled,
        examDate: srsSettings.examDate || null,
    });

    return (
        <div className="flex flex-col gap-6">
            {/* Exam mode */}
            <SettingsCard>
                <CardSection
                    title="Mode Examen Proche"
                    subtitle={`Intensifie les révisions dans les ${EXAM_MODE_WINDOW_DAYS} jours précédant un examen.`}
                    action={
                        examActive ? (
                            <span className="inline-flex items-center px-2.5 py-1 text-xs font-bold uppercase tracking-wider rounded-md bg-amber-50 dark:bg-amber-500/10 text-amber-600 dark:text-amber-500 border border-amber-200 dark:border-amber-500/30">
                                ACTIF
                            </span>
                        ) : undefined
                    }
                />

                <SettingsRow
                    label="Activer le mode examen"
                    description={`Limite l'intervalle SRS maximum à 14 jours quand l'examen est dans les ${EXAM_MODE_WINDOW_DAYS} prochains jours.`}
                >
                    <ToggleSwitch
                        checked={srsSettings.examModeEnabled}
                        onChange={checked => handleChange({ examModeEnabled: checked })}
                        aria-label="Activer le mode examen"
                    />
                </SettingsRow>

                <div className="px-6 py-5 border-t border-slate-200 dark:border-slate-700 flex flex-col gap-3">
                    <FieldLabel>Date de l'examen</FieldLabel>
                    <input
                        type="date"
                        value={srsSettings.examDate}
                        min={new Date().toISOString().split('T')[0]}
                        onChange={e => handleChange({ examDate: e.target.value })}
                        disabled={!srsSettings.examModeEnabled}
                        className={`w-full max-w-xs px-3 py-2 text-sm rounded-xl outline-none transition-all ${
                            srsSettings.examModeEnabled 
                                ? 'border-2 border-teal-500 bg-white dark:bg-slate-900 text-slate-900 dark:text-slate-100 cursor-pointer focus:ring-4 focus:ring-teal-500/20' 
                                : 'border-2 border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-950 text-slate-400 dark:text-slate-600 cursor-not-allowed opacity-75'
                        }`}
                    />

                    {/* Status banner */}
                    {srsSettings.examModeEnabled && srsSettings.examDate && (
                        <div className={`mt-2 p-3 text-sm font-medium rounded-xl border ${
                            examActive 
                                ? 'bg-amber-50 dark:bg-amber-500/10 text-amber-700 dark:text-amber-400 border-amber-200 dark:border-amber-500/30' 
                                : 'bg-teal-50 dark:bg-teal-500/10 text-teal-700 dark:text-teal-400 border-teal-200 dark:border-teal-500/30'
                        }`}>
                            {examActive
                                ? `⚡ Examen dans moins de ${EXAM_MODE_WINDOW_DAYS} jours — intervalles limités à 14 jours.`
                                : `✓ Examen planifié le ${new Date(srsSettings.examDate).toLocaleDateString('fr-FR')}. Le mode s'activera à J-${EXAM_MODE_WINDOW_DAYS}.`}
                        </div>
                    )}
                    {srsSettings.examModeEnabled && !srsSettings.examDate && (
                        <div className="mt-2 p-3 text-sm font-medium rounded-xl bg-amber-50 dark:bg-amber-500/10 text-amber-700 dark:text-amber-400 border border-amber-200 dark:border-amber-500/30">
                            Sélectionnez une date pour activer le mode examen.
                        </div>
                    )}
                </div>
            </SettingsCard>

            <SettingsCard>
                <CardSection
                    title="Options de Révision"
                    subtitle="Personnalisez votre interface et vos outils de révision."
                />
                <SettingsRow
                    label="Plein écran automatique"
                    description="Passer en plein écran au lancement d'une session."
                >
                    <ToggleSwitch
                        checked={srsSettings.autoFullscreen}
                        onChange={checked => handleChange({ autoFullscreen: checked })}
                        aria-label="Plein écran automatique"
                    />
                </SettingsRow>
                <SettingsRow
                    label="Nouvelles cartes par session"
                    description="Nombre maximum de nouvelles cartes à découvrir par session."
                >
                    <input
                        type="number"
                        min={1}
                        max={100}
                        value={srsSettings.maxNewCardsPerSession}
                        onChange={e => handleChange({ maxNewCardsPerSession: parseInt(e.target.value) || 10 })}
                        className="w-20 px-3 py-1.5 text-sm font-bold text-center bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg text-slate-900 dark:text-slate-100 focus:outline-none focus:ring-2 focus:ring-teal-500/50" 
                    />
                </SettingsRow>
                <SettingsRow
                    label="Activer le bouton Facile"
                    description="Ajoute un quatrième bouton lors des révisions pour les cartes parfaitement maîtrisées."
                    last
                >
                    <ToggleSwitch
                        checked={srsSettings.showEasyButton}
                        onChange={checked => handleChange({ showEasyButton: checked })}
                        aria-label="Activer le bouton facile"
                    />
                </SettingsRow>
            </SettingsCard>

            {/* How it works */}
            <SettingsCard>
                <CardSection title="Comment ça fonctionne ?" />
                <CardBody>
                    <ul className="list-disc pl-5 space-y-2 text-sm text-slate-500 dark:text-slate-400 marker:text-slate-300 dark:marker:text-slate-600">
                        {[
                            `En mode normal, l'algorithme SRS peut programmer une révision dans 30, 60 ou 90 jours.`,
                            `Quand l'examen est proche (J-${EXAM_MODE_WINDOW_DAYS}), l'intervalle maximum est réduit à 14 jours.`,
                            `Les cartes difficiles (faible easeFactor) continuent d'être révisées plus fréquemment.`,
                            `Le mode se désactive automatiquement une fois l'examen passé.`,
                        ].map((item, i) => (
                            <li key={i}>{item}</li>
                        ))}
                    </ul>
                </CardBody>
            </SettingsCard>
        </div>
    );
};

