import React, { useState, useRef, useEffect } from 'react';
import { CaretDown } from '@phosphor-icons/react';

export interface DropdownItem {
    id: string;
    label: string | React.ReactNode;
    icon?: React.ReactNode;
    colorClass?: string;
}

interface DropdownProps {
    value: string;
    onChange: (value: string) => void;
    options: DropdownItem[];
    placeholder?: string | React.ReactNode;
    renderTrigger?: (selectedItem?: DropdownItem, isOpen?: boolean) => React.ReactNode;
    renderOption?: (item: DropdownItem) => React.ReactNode;
    className?: string;
    dropdownClassName?: string;
    onClear?: () => void;
    showClearButton?: boolean;
}

export const Dropdown: React.FC<DropdownProps> = ({
    value,
    onChange,
    options,
    placeholder = 'Sélectionner...',
    renderTrigger,
    renderOption,
    className = '',
    dropdownClassName = '',
    onClear,
    showClearButton = false
}) => {
    const [isOpen, setIsOpen] = useState(false);
    const [focusedIndex, setFocusedIndex] = useState<number>(-1);
    const containerRef = useRef<HTMLDivElement>(null);

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (!isOpen) {
            if (e.key === 'Enter' || e.key === ' ' || e.key === 'ArrowDown') {
                e.preventDefault();
                setIsOpen(true);
            }
            return;
        }

        switch (e.key) {
            case 'ArrowDown':
                e.preventDefault();
                setFocusedIndex(prev => (prev < options.length - 1 ? prev + 1 : prev));
                break;
            case 'ArrowUp':
                e.preventDefault();
                setFocusedIndex(prev => (prev > 0 ? prev - 1 : 0));
                break;
            case 'Enter':
                e.preventDefault();
                if (focusedIndex >= 0 && focusedIndex < options.length) {
                    onChange(options[focusedIndex].id);
                    setIsOpen(false);
                }
                break;
            case 'Escape':
                e.preventDefault();
                setIsOpen(false);
                break;
        }
    };

    useEffect(() => {
        if (isOpen) {
            const index = options.findIndex(o => o.id === value);
            setFocusedIndex(index >= 0 ? index : 0);
        } else {
            setFocusedIndex(-1);
        }
    }, [isOpen, value, options]);

    const selectedItem = options.find(o => o.id === value);

    // Close on click outside
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    return (
        <div className={`relative ${className}`} ref={containerRef} onKeyDown={handleKeyDown}>
            {renderTrigger ? (
                <div onClick={() => setIsOpen(!isOpen)} className="cursor-pointer">
                    {renderTrigger(selectedItem, isOpen)}
                </div>
            ) : (
                <button
                    onClick={() => setIsOpen(!isOpen)}
                    className={`flex items-center space-x-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl px-4 py-2 hover:border-indigo-300 dark:hover:border-indigo-500/50 hover:shadow-sm transition-all outline-none cursor-pointer ${value ? 'text-indigo-600 dark:text-indigo-400' : 'text-slate-500 dark:text-slate-400'}`}
                >
                    <span className="text-sm font-bold flex-1 text-left truncate">
                        {selectedItem ? selectedItem.label : placeholder}
                    </span>
                    {showClearButton && value ? (
                        <div
                            className="ml-2 hover:bg-indigo-100 dark:hover:bg-indigo-500/20 rounded p-0.5"
                            onClick={(e) => {
                                e.stopPropagation();
                                if (onClear) onClear();
                            }}
                        >
                            &times;
                        </div>
                    ) : (
                        <CaretDown size={14} weight="bold" className="text-slate-400" />
                    )}
                </button>
            )}

            {isOpen && (
                <>
                    <div className="fixed inset-0 z-40" onClick={() => setIsOpen(false)}></div>
                    <div className={`absolute top-full left-0 mt-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-lg z-50 p-2 min-w-[240px] max-h-[300px] overflow-y-auto flex flex-col gap-1 custom-scrollbar w-full sm:w-auto ${dropdownClassName}`}>
                        {options.length === 0 ? (
                            <div className="text-xs text-slate-500 text-center py-4">Aucune option</div>
                        ) : (
                            options.map((option, index) => (
                                <button
                                    key={option.id}
                                    onClick={() => {
                                        onChange(option.id);
                                        setIsOpen(false);
                                    }}
                                    className={`flex items-center gap-3 px-3 py-2 rounded-lg border-none bg-transparent cursor-pointer text-left w-full ${focusedIndex === index ? 'bg-slate-100 dark:bg-slate-800' : 'hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                                >
                                    {renderOption ? (
                                        renderOption(option)
                                    ) : (
                                        <>
                                            {option.icon && <div className={option.colorClass}>{option.icon}</div>}
                                            <span className="text-sm font-bold text-slate-700 dark:text-slate-200 truncate uppercase tracking-wider">{option.label}</span>
                                        </>
                                    )}
                                </button>
                            ))
                        )}
                    </div>
                </>
            )}
        </div>
    );
};

import React, { useState, useRef } from 'react';
import { createPortal } from 'react-dom';
import { useCardStore } from '../../store/useCardStore';
import { Brain, Cards, Warning, TextAa } from '@phosphor-icons/react';

interface InteractiveCardLinkProps {
    target: string;
    children: React.ReactNode;
    onClick?: (target: string) => void;
}

export const InteractiveCardLink: React.FC<InteractiveCardLinkProps> = ({ target, children, onClick }) => {
    const { cards } = useCardStore();
    const [isHovered, setIsHovered] = useState(false);
    const [coords, setCoords] = useState({ top: 0, left: 0 });
    const linkRef = useRef<HTMLAnchorElement>(null);
    const hoverTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);
    const leaveTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);

    const matchedCard = React.useMemo(() => {
        return cards.find(c => c.title.trim().toLowerCase() === target.trim().toLowerCase());
    }, [cards, target]);

    const handleMouseEnter = () => {
        if (leaveTimeout.current) clearTimeout(leaveTimeout.current);
        hoverTimeout.current = setTimeout(() => {
            if (linkRef.current) {
                const rect = linkRef.current.getBoundingClientRect();
                setCoords({
                    top: rect.bottom + window.scrollY + 8,
                    left: rect.left + window.scrollX
                });
            }
            setIsHovered(true);
        }, 300); // 300ms delay before showing popover
    };

    const handleMouseLeave = () => {
        if (hoverTimeout.current) clearTimeout(hoverTimeout.current);
        leaveTimeout.current = setTimeout(() => {
            setIsHovered(false);
        }, 200); // 200ms grace period to let user move mouse into popover
    };

    const popoverContent = matchedCard ? (
        <div 
            className="card-link-popover absolute z-[9999] w-[320px] bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-2xl p-4 transition-all animate-in fade-in slide-in-from-top-2"
            style={{ top: coords.top, left: coords.left }}
            onMouseEnter={() => {
                if (leaveTimeout.current) clearTimeout(leaveTimeout.current);
                setIsHovered(true);
            }}
            onMouseLeave={handleMouseLeave}
            onClick={(e) => {
                e.stopPropagation();
            }}
        >
            <div className="flex items-center gap-2 mb-2">
                {matchedCard.nodeType === 'concept' ? (
                    <Brain weight="duotone" className="text-purple-500" size={20} />
                ) : matchedCard.nodeType === 'flashcard' ? (
                    <Cards weight="duotone" className="text-green-500" size={20} />
                ) : (
                    <TextAa weight="duotone" className="text-blue-500" size={20} />
                )}
                <span className="text-xs font-semibold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                    {matchedCard.nodeType}
                </span>
            </div>

            <h4 className="text-[1.05rem] font-bold text-slate-900 dark:text-white mb-2 leading-tight">
                {matchedCard.title}
            </h4>

            <p className="text-sm text-slate-600 dark:text-slate-300 line-clamp-3">
                {matchedCard.content || "Aucun contenu résumé."}
            </p>

            <button 
                onClick={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    if (onClick) onClick(target);
                    setIsHovered(false);
                }}
                className="mt-4 w-full py-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-900 dark:text-slate-100 rounded-lg text-sm font-semibold transition-colors"
            >
                Ouvrir la carte
            </button>
        </div>
    ) : (
        <div 
            className="card-link-popover absolute z-[9999] w-[280px] bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-2xl p-4 transition-all animate-in fade-in slide-in-from-top-2"
            style={{ top: coords.top, left: coords.left }}
            onMouseEnter={() => {
                if (leaveTimeout.current) clearTimeout(leaveTimeout.current);
                setIsHovered(true);
            }}
            onMouseLeave={handleMouseLeave}
        >
            <div className="flex items-center gap-2 mb-2 text-amber-500">
                <Warning weight="fill" size={20} />
                <span className="text-xs font-semibold uppercase tracking-wider">
                    Lien Orphelin
                </span>
            </div>
            <p className="text-sm text-slate-600 dark:text-slate-300">
                La carte "{target}" est introuvable ou a été supprimée.
            </p>
        </div>
    );

    return (
        <>
            <a 
                ref={linkRef}
                href={`#internal:${target}`}
                className={`inline-flex items-center gap-1 font-semibold cursor-pointer border-b transition-colors no-underline px-1 rounded-sm ${matchedCard ? 'text-teal-700 dark:text-teal-400 border-teal-200 dark:border-teal-800 hover:bg-teal-50 dark:hover:bg-teal-900/30' : 'text-slate-500 border-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                onMouseEnter={handleMouseEnter}
                onMouseLeave={handleMouseLeave}
                onClick={(e) => {
                    e.preventDefault();
                    if (onClick) onClick(target);
                }}
            >
                {matchedCard?.nodeType === 'concept' && <Brain size={16} weight="duotone" className="opacity-70" />}
                {matchedCard?.nodeType === 'flashcard' && <Cards size={16} weight="duotone" className="opacity-70" />}
                {children}
            </a>

            {isHovered && createPortal(popoverContent, document.body)}
        </>
    );
};

import React from 'react';
import { X, CheckCircle, WarningCircle, Info, Warning } from '@phosphor-icons/react';
import { useToastStore } from '../../store/useToastStore';
import type { ToastVariant } from '../../store/useToastStore';


const VARIANT_STYLES: Record<ToastVariant, { bg: string; border: string; icon: React.ReactNode }> = {
  success: {
    bg: '#10b981',
    border: 'rgba(16,185,129,0.3)',
    icon: <CheckCircle size={18} weight="fill" />,
  },
  error: {
    bg: '#f43f5e',
    border: 'rgba(244,63,94,0.3)',
    icon: <WarningCircle size={18} weight="fill" />,
  },
  warning: {
    bg: '#f59e0b',
    border: 'rgba(245,158,11,0.3)',
    icon: <Warning size={18} weight="fill" />,
  },
  info: {
    bg: '#3b82f6',
    border: 'rgba(59,130,246,0.3)',
    icon: <Info size={18} weight="fill" />,
  },
};

export const ToastContainer: React.FC = () => {
  const { toasts, dismiss } = useToastStore();

  if (toasts.length === 0) return null;

  return (
    <div
      className="toastcontainer-style-1" 
      aria-live="polite"
      aria-label="Notifications"
    >
      {toasts.map((t) => {
        const style = VARIANT_STYLES[t.variant];
        return (
          <div
            key={t.id}
            role="status"
            className="toastcontainer-style-2" style={{
  background: style.bg,
  boxShadow: `0 8px 24px ${style.border.replace('0.3', '0.4')}`
}}
          >
            {style.icon}
            <span className="toastcontainer-style-3" >{t.message}</span>
            {t.action && (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  t.action!.onClick();
                  dismiss(t.id);
                }}
                className="toastcontainer-style-4" 
                onMouseOver={(e) => e.currentTarget.style.background = 'rgba(255,255,255,0.3)'}
                onMouseOut={(e) => e.currentTarget.style.background = 'rgba(255,255,255,0.2)'}
              >
                {t.action.label}
              </button>
            )}
            <button
              onClick={() => dismiss(t.id)}
              aria-label="Fermer la notification"
              className="toastcontainer-style-5" 
            >
              <X size={14} weight="bold" />
            </button>
          </div>
        );
      })}
      <style>{`
        @keyframes toastIn {
          from { opacity: 0; transform: translateY(12px) scale(0.96); }
          to   { opacity: 1; transform: translateY(0)    scale(1);    }
        }
      `}</style>
    </div>
  );
};

import React, { createContext, useContext, useEffect, useState } from 'react';
import {
    onAuthStateChanged,
    signInWithPopup,
    GoogleAuthProvider,
    signOut,
    createUserWithEmailAndPassword,
    signInWithEmailAndPassword,
    updateProfile,
    sendPasswordResetEmail,
} from 'firebase/auth';
import type { User } from 'firebase/auth';
import { auth } from '../lib/firebase';
import { setStorageUid } from '../storage';
import { useCardStore } from '../store/useCardStore';

interface AuthContextType {
    user: User | null;
    loading: boolean;
    signInWithGoogle: () => Promise<void>;
    signUpWithEmail: (email: string, password: string, displayName: string) => Promise<void>;
    signInWithEmail: (email: string, password: string) => Promise<void>;
    resetPassword: (email: string) => Promise<void>;
    logout: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType>({
    user: null,
    loading: true,
    signInWithGoogle: async () => {},
    signUpWithEmail: async () => {},
    signInWithEmail: async () => {},
    resetPassword: async () => {},
    logout: async () => {},
});

export const useAuth = () => useContext(AuthContext);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [user, setUser] = useState<User | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        let prevUid = user?.uid;
        const unsubscribe = onAuthStateChanged(auth, async (currentUser) => {
            const currentUid = currentUser?.uid;

            if (currentUid !== prevUid) {
                prevUid = currentUid;
                setStorageUid(currentUid || null);
                if (currentUid) {
                    await useCardStore.getState().reloadFromStorage();
                } else {
                    useCardStore.getState().clearStore();
                }
            }

            setUser(currentUser);
            setLoading(false);
        });
        return () => unsubscribe();
    }, []);

    const signInWithGoogle = async () => {
        const provider = new GoogleAuthProvider();
        await signInWithPopup(auth, provider);
    };

    const signUpWithEmail = async (email: string, password: string, displayName: string) => {
        const cred = await createUserWithEmailAndPassword(auth, email, password);
        await updateProfile(cred.user, { displayName });
    };

    const signInWithEmail = async (email: string, password: string) => {
        await signInWithEmailAndPassword(auth, email, password);
    };

    const resetPassword = async (email: string) => {
        await sendPasswordResetEmail(auth, email);
    };

    const logout = async () => {
        await signOut(auth);
    };

    return (
        <AuthContext.Provider value={{ user, loading, signInWithGoogle, signUpWithEmail, signInWithEmail, resetPassword, logout }}>
            {children}
        </AuthContext.Provider>
    );
};

import React, { createContext, useContext, useState, useEffect, useMemo, useCallback } from 'react';
import { CARD_COLORS as DEFAULT_CARD_COLORS, DEFAULT_CARD_ICONS } from '../theme';
import { loadSettingAsync, loadSettingSync, removeSettingAsync, saveSettingAsync } from '../persistentSettings';

// Define the shape of our context
interface ThemeContextType {
    categoryColors: Record<string, string>;
    categoryIcons: Record<string, string>;
    setCategoryColor: (type: string, color: string) => void;
    setCategoryIcon: (type: string, iconName: string) => void;
    resetCategoryColors: () => void;
    resetCategoryIcons: () => void;
    getCategoryColor: (type: string) => string;
    getCategoryIcon: (type: string) => string;
    darkMode: boolean;
    themeMode: 'light' | 'dark' | 'system';
    setThemeMode: (mode: 'light' | 'dark' | 'system') => void;
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

const STORAGE_KEY_COLORS = 'pharmabrain_theme_colors';
const STORAGE_KEY_ICONS = 'pharmabrain_theme_icons';
const STORAGE_KEY_THEME_MODE = 'pharmabrain_theme_mode';

export const ThemeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [themeMode, setThemeModeState] = useState<'light' | 'dark' | 'system'>(() => {
        const stored = loadSettingSync<string>(STORAGE_KEY_THEME_MODE, 'system');
        return (stored as 'light' | 'dark' | 'system') || 'system';
    });

    const [darkMode, setDarkMode] = useState<boolean>(false);

    useEffect(() => {
        loadSettingAsync<string>(STORAGE_KEY_THEME_MODE, 'system').then(stored => {
            if (stored === 'light' || stored === 'dark' || stored === 'system') {
                setThemeModeState(stored);
            }
        });
    }, []);

    useEffect(() => {
        const applyTheme = () => {
            let isDark = false;
            if (themeMode === 'system') {
                isDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
            } else {
                isDark = themeMode === 'dark';
            }
            setDarkMode(isDark);
            document.documentElement.classList.toggle('dark', isDark);
            saveSettingAsync(STORAGE_KEY_THEME_MODE, themeMode);
        };

        applyTheme();

        if (themeMode === 'system') {
            const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
            const handler = () => applyTheme();
            mediaQuery.addEventListener('change', handler);
            return () => mediaQuery.removeEventListener('change', handler);
        }
    }, [themeMode]);

    const setThemeMode = (mode: 'light' | 'dark' | 'system') => {
        setThemeModeState(mode);
    };

    // Initialize state for Colors
    const [categoryColors, setCategoryColors] = useState<Record<string, string>>(() => {
        const stored = loadSettingSync<Record<string, string> | null>(STORAGE_KEY_COLORS, null);
        if (stored) {
            return { ...DEFAULT_CARD_COLORS, ...stored };
        }
        return { ...DEFAULT_CARD_COLORS };
    });

    // Initialize state for Icons
    const [categoryIcons, setCategoryIcons] = useState<Record<string, string>>(() => {
        const stored = loadSettingSync<Record<string, string> | null>(STORAGE_KEY_ICONS, null);
        if (stored) {
            return { ...DEFAULT_CARD_ICONS, ...stored };
        }
        return { ...DEFAULT_CARD_ICONS };
    });

    useEffect(() => {
        loadSettingAsync<Record<string, string> | null>(STORAGE_KEY_COLORS, null).then((stored) => {
            if (stored) setCategoryColors({ ...DEFAULT_CARD_COLORS, ...stored });
        });
        loadSettingAsync<Record<string, string> | null>(STORAGE_KEY_ICONS, null).then((stored) => {
            if (stored) setCategoryIcons({ ...DEFAULT_CARD_ICONS, ...stored });
        });
    }, []);

    // Save Colors to localStorage
    useEffect(() => {
        saveSettingAsync(STORAGE_KEY_COLORS, categoryColors);
    }, [categoryColors]);

    // Save Icons to localStorage
    useEffect(() => {
        saveSettingAsync(STORAGE_KEY_ICONS, categoryIcons);
    }, [categoryIcons]);


    const setCategoryColor = useCallback((type: string, color: string) => {
        setCategoryColors(prev => ({
            ...prev,
            [type]: color
        }));
    }, []);

    const setCategoryIcon = useCallback((type: string, iconName: string) => {
        setCategoryIcons(prev => ({
            ...prev,
            [type]: iconName
        }));
    }, []);


    const resetCategoryColors = useCallback(() => {
        setCategoryColors({ ...DEFAULT_CARD_COLORS });
        removeSettingAsync(STORAGE_KEY_COLORS);
    }, []);

    const resetCategoryIcons = useCallback(() => {
        setCategoryIcons({ ...DEFAULT_CARD_ICONS });
        removeSettingAsync(STORAGE_KEY_ICONS);
    }, []);

    // Helper to get color
    const getCategoryColor = useCallback((type: string): string => {
        if (categoryColors[type]) {
            return categoryColors[type];
        }
        // Fallback generation for dynamic types
        let hash = 0;
        for (let i = 0; i < type.length; i++) {
            hash = type.charCodeAt(i) + ((hash << 5) - hash);
        }
        const h = Math.abs(hash) % 360;
        const s = 0.65;
        const l = 0.45;
        const c = (1 - Math.abs(2 * l - 1)) * s;
        const x = c * (1 - Math.abs((h / 60) % 2 - 1));
        const m = l - c / 2;
        let r = 0, g = 0, b = 0;
        if (0 <= h && h < 60) { r = c; g = x; b = 0; }
        else if (60 <= h && h < 120) { r = x; g = c; b = 0; }
        else if (120 <= h && h < 180) { r = 0; g = c; b = x; }
        else if (180 <= h && h < 240) { r = 0; g = x; b = c; }
        else if (240 <= h && h < 300) { r = x; g = 0; b = c; }
        else if (300 <= h && h < 360) { r = c; g = 0; b = x; }
        const toHex = (n: number) => {
            const hex = Math.round((n + m) * 255).toString(16);
            return hex.length === 1 ? '0' + hex : hex;
        };
        return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
    }, [categoryColors]);

    // Helper to get icon
    const getCategoryIcon = useCallback((type: string): string => {
        if (categoryIcons[type]) {
            return categoryIcons[type];
        }
        return 'FileText'; // Default fallback icon
    }, [categoryIcons]);

    const contextValue = useMemo(() => ({
        categoryColors,
        categoryIcons,
        setCategoryColor,
        setCategoryIcon,
        resetCategoryColors,
        resetCategoryIcons,
        getCategoryColor,
        getCategoryIcon,
        darkMode,
        themeMode,
        setThemeMode
    }), [
        categoryColors, categoryIcons, setCategoryColor, setCategoryIcon,
        resetCategoryColors, resetCategoryIcons, getCategoryColor, getCategoryIcon,
        darkMode, themeMode
    ]);

    return (
        <ThemeContext.Provider value={contextValue}>
            {children}
        </ThemeContext.Provider>
    );
};

export const useTheme = () => {
    const context = useContext(ThemeContext);
    if (context === undefined) {
        throw new Error('useTheme must be used within a ThemeProvider');
    }
    return context;
};

import React, { createContext, useContext, useState, useCallback, useMemo } from 'react';
import type { ReactNode } from 'react';
import { CheckCircle, XCircle, Info, Warning, X } from '@phosphor-icons/react';

export type ToastType = 'success' | 'error' | 'info' | 'warning';

interface ToastMessage {
  id: string;
  message: string;
  type: ToastType;
}

interface ToastContextProps {
  showToast: (message: string, type?: ToastType) => void;
}

const ToastContext = createContext<ToastContextProps | undefined>(undefined);

export const ToastProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [toasts, setToasts] = useState<ToastMessage[]>([]);

  const showToast = useCallback((message: string, type: ToastType = 'info') => {
    const id = Math.random().toString(36).substring(2, 9);
    setToasts((prev) => [...prev, { id, message, type }]);

    setTimeout(() => {
      setToasts((prev) => prev.filter((t) => t.id !== id));
    }, 3000);
  }, []);

  const removeToast = (id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  };

  const contextValue = useMemo(() => ({ showToast }), [showToast]);

  return (
    <ToastContext.Provider value={contextValue}>
      {children}
      <div className="fixed bottom-6 left-1/2 -translate-x-1/2 flex flex-col gap-2 z-[9999] pointer-events-none">
        {toasts.map((toast) => (
          <div
            key={toast.id}
            className={`pointer-events-auto flex items-center gap-3 px-4 py-3 bg-white dark:bg-slate-900 border rounded-lg shadow-lg text-slate-900 dark:text-slate-100 min-w-[300px] max-w-[80vw] animate-[toast-in_0.3s_cubic-bezier(0.16,1,0.3,1)] ${
                toast.type === 'error' ? 'border-red-500/50' : 
                toast.type === 'success' ? 'border-emerald-500/50' : 
                toast.type === 'warning' ? 'border-amber-500/50' : 
                'border-slate-200 dark:border-slate-800'
            }`}
          >
            {toast.type === 'success' && <CheckCircle size={20} className="text-emerald-500 shrink-0" />}
            {toast.type === 'error' && <XCircle size={20} className="text-red-500 shrink-0" />}
            {toast.type === 'warning' && <Warning size={20} className="text-amber-500 shrink-0" />}
            {toast.type === 'info' && <Info size={20} className="text-blue-500 shrink-0" />}

            <span className="flex-1 text-[0.9rem] font-medium">{toast.message}</span>

            <button 
              onClick={() => removeToast(toast.id)}
              className="bg-transparent border-none text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 cursor-pointer p-1 flex shrink-0 transition-colors"
            >
              <X size={16} />
            </button>
          </div>
        ))}
      </div>
    </ToastContext.Provider>
  );
};

export const useToast = () => {
  const context = useContext(ToastContext);
  if (!context) {
    throw new Error('useToast must be used within a ToastProvider');
  }
  return context;
};

/**
 * Voy Vector Store - WASM-based high-performance vector search
 * Now supports sharding (multiple Voy instances per subject/course)
 */
import { Voy } from 'voy-search';
import { getDB, isElectron } from '../storage';

export interface EmbeddingEntry {
    id: string;
    title: string;
    embeddings: number[];
    shardId?: string; // Optional shard identifier (e.g., courseId or subject)
}

export class VoyVectorStore {
    // Map of shardId -> Voy instance
    private indices = new Map<string, any>();
    // Global embedding cache for O(1) lookups: Map<cardId, embedding>
    private embeddingCache = new Map<string, number[]>();
    // Track which shard each card belongs to: Map<cardId, shardId>
    private cardShardMap = new Map<string, string>();

    constructor() {
        // We always initialize a 'global' shard as default
        this.getOrCreateIndex('global');
    }

    /**
     * Helper to get or create an index for a given shardId
     */
    private getOrCreateIndex(shardId: string): any {
        let index = this.indices.get(shardId);
        if (!index) {
            index = new Voy();
            this.indices.set(shardId, index);
        }
        return index;
    }

    /**
     * Get embedding by ID
     */
    getEmbedding(id: string): number[] | undefined {
        return this.embeddingCache.get(id);
    }

    /**
     * Add items to the index, routing them to the correct shards
     */
    add(items: EmbeddingEntry[]): void {
        // Group items by shardId
        const chunksByShard = new Map<string, any[]>();

        items.forEach(item => {
            const shardId = item.shardId || 'global';

            // Cache the embedding globally
            if (item.embeddings) {
                this.embeddingCache.set(item.id, Array.isArray(item.embeddings) ? item.embeddings : Array.from(item.embeddings));
                this.cardShardMap.set(item.id, shardId);
            }

            if (!chunksByShard.has(shardId)) {
                chunksByShard.set(shardId, []);
            }

            chunksByShard.get(shardId)!.push({
                id: item.id,
                title: item.title,
                url: '', // Explicitly add empty URL as required by Voy Resource type
                embeddings: Array.isArray(item.embeddings) ? item.embeddings : Array.from(item.embeddings || [])
            });
        });

        // Add to each shard's index
        for (const [shardId, shardItems] of chunksByShard.entries()) {
            const index = this.getOrCreateIndex(shardId);
            try {
                // Sanitize in chunks
                const CHUNK_SIZE = 100;
                for (let i = 0; i < shardItems.length; i += CHUNK_SIZE) {
                    const chunk = shardItems.slice(i, i + CHUNK_SIZE);
                    const cleanChunk = JSON.parse(JSON.stringify(chunk));

                    if (cleanChunk.length > 0) {
                        index.add({ embeddings: cleanChunk });
                    }
                }
            } catch (e) {
                if (e instanceof Error && (e.message.includes('recursive') || e.message.includes('unreachable'))) {
                    this.indices.set(shardId, new Voy());
                }
            }
        }
    }

    /**
     * Search for similar items across specified shards (or 'global' + specific shards)
     */
    search(queryEmbedding: number[], k: number = 10, targetShardIds?: string[]): { id: string; similarity: number }[] {
        // If no target shards specified, search across all currently loaded shards
        const shardsToSearch = targetShardIds && targetShardIds.length > 0 
            ? targetShardIds.map(id => this.indices.get(id)).filter(idx => !!idx)
            : Array.from(this.indices.values());

        if (shardsToSearch.length === 0) return [];

        try {
            const allResults: { id: string; similarity: number }[] = [];

            for (const index of shardsToSearch) {
                const results = index.search(queryEmbedding, k);
                if (results && Array.isArray(results)) {
                    results.forEach((r: { id: string; score: number }) => {
                        allResults.push({ id: r.id, similarity: r.score || 0 });
                    });
                }
            }

            // Sort merged results by similarity (descending) and take top K
            return allResults
                .sort((a, b) => b.similarity - a.similarity)
                .slice(0, k);

        } catch (e) {
            return [];
        }
    }

    /**
     * Serialize a specific shard and its subset of the cache
     */
    serializeShard(shardId: string): Uint8Array {
        const index = this.indices.get(shardId);
        if (!index) return new Uint8Array(0);

        let indexData: Uint8Array;
        try {
            const serialized = index.serialize();
            indexData = new TextEncoder().encode(serialized);
        } catch (e) {
            return new Uint8Array(0);
        }

        // Serialize only cache entries for this shard
        const shardCacheEntries = Array.from(this.cardShardMap.entries())
            .filter(([_, mappedShardId]) => mappedShardId === shardId)
            .map(([cardId, _]) => {
                const emb = this.embeddingCache.get(cardId);
                return [cardId, emb] as [string, number[]];
            })
            .filter(([_, emb]) => !!emb);

        const cacheData = new TextEncoder().encode(JSON.stringify(shardCacheEntries));
        const header = new TextEncoder().encode("VOY+CACHE_V2"); // 12 bytes
        const lengthBuffer = new ArrayBuffer(4);
        new DataView(lengthBuffer).setUint32(0, indexData.length, true);

        const combined = new Uint8Array(header.length + 4 + indexData.length + cacheData.length);
        combined.set(header, 0);
        combined.set(new Uint8Array(lengthBuffer), header.length);
        combined.set(indexData, header.length + 4);
        combined.set(cacheData, header.length + 4 + indexData.length);

        return combined;
    }

    /**
     * Deserialize a shard and inject its subset of the cache
     */
    deserializeShard(data: Uint8Array, shardId: string): void {
        const headerV2 = new TextEncoder().encode("VOY+CACHE_V2");
        const headerV1 = new TextEncoder().encode("VOY+CACHE");

        const hasHeader = (header: Uint8Array) => {
            if (data.length < header.length + 4) return false;
            for (let i = 0; i < header.length; i++) {
                if (data[i] !== header[i]) return false;
            }
            return true;
        };

        if (hasHeader(headerV2)) {
            try {
                const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
                const indexLength = view.getUint32(headerV2.length, true);

                const indexData = data.subarray(headerV2.length + 4, headerV2.length + 4 + indexLength);
                const cacheData = data.subarray(headerV2.length + 4 + indexLength);

                const indexString = new TextDecoder().decode(indexData);
                this.indices.set(shardId, Voy.deserialize(indexString));

                const cacheJson = new TextDecoder().decode(cacheData);
                const entries: [string, number[]][] = JSON.parse(cacheJson);

                for (const [cardId, emb] of entries) {
                    this.embeddingCache.set(cardId, emb);
                    this.cardShardMap.set(cardId, shardId);
                }
            } catch (e) {
                this.indices.set(shardId, new Voy());
            }
        } else if (hasHeader(headerV1)) {
            this.indices.set(shardId, new Voy());
        } else {
            // Legacy monolithic format (assume it's the global shard)
            try {
                const indexString = new TextDecoder().decode(data);
                if (indexString && indexString.trim().length > 0 && indexString.trim().startsWith('{')) {
                    this.indices.set(shardId, Voy.deserialize(indexString));
                } else {
                    this.indices.set(shardId, new Voy());
                }
            } catch (e) {
                this.indices.set(shardId, new Voy());
            }
        }
    }

    /**
     * Clear all indices and cache
     */
    clear(): void {
        this.indices.clear();
        this.embeddingCache.clear();
        this.cardShardMap.clear();
        this.getOrCreateIndex('global');
    }

    /**
     * Get size 
     */
    get size(): number {
        return this.embeddingCache.size;
    }

    /**
     * Check if a shard is currently loaded in memory
     */
    isShardLoaded(shardId: string): boolean {
        return this.indices.has(shardId);
    }

    /**
     * Load a specific shard from disk/IndexedDB
     */
    async load(shardId: string = 'global'): Promise<boolean> {
        if (this.isShardLoaded(shardId) && shardId !== 'global') {
            return true; // Already loaded
        }

        if (isElectron() && window.electronAPI?.loadVectorIndex) {
            try {
                const data = await window.electronAPI.loadVectorIndex(shardId);
                if (data) {
                    this.deserializeShard(data, shardId);
                    return true;
                }
            } catch (e) {
            }
        } else {
            // IndexedDB Fallback for Web
            try {
                const db = getDB();
                const record = await db.vectorIndices.get(shardId);
                if (record && record.data) {
                    this.deserializeShard(record.data, shardId);
                    return true;
                }
            } catch (e) {
            }
        }

        // If it wasn't found, ensure an empty index exists
        this.getOrCreateIndex(shardId);
        return false;
    }

    /**
     * Save a specific shard to disk/IndexedDB
     */
    async save(shardId: string = 'global'): Promise<void> {
        const data = this.serializeShard(shardId);
        if (data.length === 0) return;

        if (isElectron() && window.electronAPI?.saveVectorIndex) {
            try {
                await window.electronAPI.saveVectorIndex(data, shardId);
            } catch (e) {
            }
        } else {
            // IndexedDB Fallback for Web
            try {
                const db = getDB();
                await db.vectorIndices.put({ shardId, data });
            } catch (e) {
            }
        }
    }

    /**
     * Helper to save all currently loaded shards
     */
    async saveAllLoadedShards(): Promise<void> {
        const promises = Array.from(this.indices.keys()).map(shardId => this.save(shardId));
        await Promise.allSettled(promises);
    }
}

// Singleton instance
export const vectorStore = new VoyVectorStore();

import { useRef } from 'react';

export const useNetworkCamera = (use3D: boolean) => {
    const fgRef = useRef<any>(null);
    const hasCenteredRef = useRef(false);

    const handleZoomIn = () => {
        if (!fgRef.current) return;
        if (!use3D && fgRef.current.zoom) {
            const currentZoom = fgRef.current.zoom();
            fgRef.current.zoom(currentZoom * 1.5, 400);
        } else if (use3D && fgRef.current.cameraPosition) {
            const pos = fgRef.current.cameraPosition();
            fgRef.current.cameraPosition({ x: pos.x * 0.7, y: pos.y * 0.7, z: pos.z * 0.7 }, { x: 0, y: 0, z: 0 }, 400);
        }
    };

    const handleZoomOut = () => {
        if (!fgRef.current) return;
        if (!use3D && fgRef.current.zoom) {
            const currentZoom = fgRef.current.zoom() as unknown as number;
            fgRef.current.zoom(currentZoom / 1.5, 400);
        } else if (use3D && fgRef.current.cameraPosition) {
            const pos = fgRef.current.cameraPosition();
            fgRef.current.cameraPosition({ x: pos.x * 1.4, y: pos.y * 1.4, z: pos.z * 1.4 }, { x: 0, y: 0, z: 0 }, 400);
        }
    };

    const handleFitView = () => {
        if (!fgRef.current) return;
        if (!use3D && fgRef.current.zoomToFit) {
            fgRef.current.zoomToFit(400, 50);
        } else if (use3D && fgRef.current.cameraPosition) {
            // For 3D, move camera to a default reasonable distance
            fgRef.current.cameraPosition({ x: 0, y: 0, z: 800 }, { x: 0, y: 0, z: 0 }, 1000);
        }
    };

    const handleEngineStop = (activeNodeId?: string | null) => {
        if (!hasCenteredRef.current && fgRef.current && !activeNodeId && !use3D && fgRef.current.zoomToFit) {
            fgRef.current.zoomToFit(400, 50);
            hasCenteredRef.current = true;
        } else if (!hasCenteredRef.current && fgRef.current && !activeNodeId && use3D && fgRef.current.cameraPosition) {
            fgRef.current.cameraPosition({ x: 0, y: 0, z: 800 }, { x: 0, y: 0, z: 0 }, 1000);
            hasCenteredRef.current = true;
        }
    };

    return {
        fgRef,
        hasCenteredRef,
        handleZoomIn,
        handleZoomOut,
        handleFitView,
        handleEngineStop
    };
};

import { useState, useEffect } from 'react';

export const useNetworkDimensions = (
    containerRef: React.RefObject<HTMLDivElement>,
    fgRef: React.MutableRefObject<any>
) => {
    const [dimensions, setDimensions] = useState({ width: window.innerWidth, height: window.innerHeight });
    const [isFullscreen, setIsFullscreen] = useState(false);

    useEffect(() => {
        if (!containerRef.current) return;

        // Auto-resize
        const resizeObserver = new ResizeObserver(entries => {
            for (const entry of entries) {
                if (entry.contentRect.width > 0 && entry.contentRect.height > 0) {
                    setDimensions({
                        width: entry.contentRect.width,
                        height: entry.contentRect.height
                    });
                }
            }
        });
        resizeObserver.observe(containerRef.current);

        // Visibility / intersection for performance (P-4)
        const intersectionObserver = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (fgRef.current) {
                    if (entry.isIntersecting && document.visibilityState === 'visible') {
                        fgRef.current.resumeAnimation?.();
                    } else {
                        fgRef.current.pauseAnimation?.();
                    }
                }
            });
        }, { threshold: 0.1 });
        intersectionObserver.observe(containerRef.current);

        const handleVisibilityChange = () => {
            if (fgRef.current) {
                if (document.visibilityState === 'visible') {
                    fgRef.current.resumeAnimation?.();
                } else {
                    fgRef.current.pauseAnimation?.();
                }
            }
        };

        const handleHeavyIndexing = (e: Event) => {
            const customEvent = e as CustomEvent<{ isIndexing: boolean }>;
            if (fgRef.current) {
                if (customEvent.detail.isIndexing) {
                    fgRef.current.pauseAnimation?.();
                } else if (document.visibilityState === 'visible') {
                    fgRef.current.resumeAnimation?.();
                }
            }
        };

        document.addEventListener('visibilitychange', handleVisibilityChange);
        window.addEventListener('heavy-indexing-status', handleHeavyIndexing);

        return () => {
            resizeObserver.disconnect();
            intersectionObserver.disconnect();
            document.removeEventListener('visibilitychange', handleVisibilityChange);
            window.removeEventListener('heavy-indexing-status', handleHeavyIndexing);
        };
    }, [containerRef, fgRef]);

    useEffect(() => {
        const handleFullscreenChange = () => {
            setIsFullscreen(!!document.fullscreenElement);
        };
        document.addEventListener('fullscreenchange', handleFullscreenChange);
        return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
    }, []);

    const toggleFullscreen = () => {
        if (!containerRef.current) return;
        if (!document.fullscreenElement) {
            containerRef.current.requestFullscreen().catch(err => {
                console.error(`Error attempting to enable fullscreen: ${err.message}`);
            });
        } else {
            document.exitFullscreen();
        }
    };

    return {
        dimensions,
        isFullscreen,
        toggleFullscreen
    };
};

import { useState, useEffect, useRef } from 'react';
import { useCardStore } from '../store/useCardStore';
import { loadCardsAsync, saveCardsAsync } from '../storage';
import { initialCards } from '../data';
import { initSemanticSearch, buildCardEmbeddings } from '../semanticSearch';
import { loadFeedback } from '../linkFeedback';
import { loadSettingAsync, saveSettingAsync } from '../persistentSettings';
import { rebuildIndex } from '../searchIndex';
import type { Card } from '../types';

type Workspace = { id: string; name: string; createdAt: number; updatedAt: number };

const WORKSPACES_KEY = 'pharmabrain_workspaces_v1';
const ACTIVE_WORKSPACE_KEY = 'pharmabrain_active_workspace_v1';
const DEFAULT_WORKSPACE_ID = 'workspace-default';
const INITIAL_LOAD_SEED_COUNT = 6;

function buildWorkspaceSeedCards(workspaceId: string, limit: number): Card[] {
    const seeds = initialCards.slice(0, Math.min(limit, initialCards.length));
    const seedIds = new Set(seeds.map(card => card.id));
    const now = Date.now();

    return seeds.map((card) => ({
      ...card,
      id: `${workspaceId}-${card.id}`,
      workspaceId,
      createdAt: now,
      updatedAt: now,
      manualConnections: card.manualConnections
        ?.filter(targetId => seedIds.has(targetId))
        .map(targetId => `${workspaceId}-${targetId}`)
    }));
}

export function useAppInitialization() {
    const { cards, setIsLoading, setCards } = useCardStore();
    const [semanticReady, setSemanticReady] = useState(false);
    const [embeddingsReady, setEmbeddingsReady] = useState(false);

    // Initialize semantic search (loads model in background)
    useEffect(() => {
        let lastLog = 0;
        initSemanticSearch(
        (progress) => {
            if (progress >= 100 || progress - lastLog >= 10) {
            lastLog = progress;
            }
        },
        () => {
            setSemanticReady(true);
        }
        );
    }, []);

    // Load data
    useEffect(() => {
        const loadData = async () => {
            setIsLoading(true);
            try {
                if (window.electronAPI?.loadAbbreviations) {
                    const savedAbbrevs = await window.electronAPI.loadAbbreviations();
                    const { loadLearnedAbbreviations } = await import('../learnedAbbreviations');
                    loadLearnedAbbreviations(savedAbbrevs);
                }

                loadFeedback();

                const [loadedCards, storedWorkspaces, storedActiveWorkspace] = await Promise.all([
                    loadCardsAsync(),
                    loadSettingAsync<Workspace[]>(WORKSPACES_KEY, []),
                    loadSettingAsync<string>(ACTIVE_WORKSPACE_KEY, DEFAULT_WORKSPACE_ID)
                ]);

                const normalizedWorkspaces = storedWorkspaces.length > 0
                    ? storedWorkspaces
                    : [{ id: DEFAULT_WORKSPACE_ID, name: 'Espace principal', createdAt: Date.now(), updatedAt: Date.now() }];

                const workspaceIdSet = new Set(normalizedWorkspaces.map(w => w.id));
                const migratedCards = loadedCards.map(card => {
                    const workspaceId = card.workspaceId && workspaceIdSet.has(card.workspaceId)
                    ? card.workspaceId
                    : normalizedWorkspaces[0].id;
                    return { ...card, workspaceId };
                });

                const activeWorkspace = normalizedWorkspaces.some(w => w.id === storedActiveWorkspace)
                    ? storedActiveWorkspace
                    : normalizedWorkspaces[0].id;

                await Promise.all([
                    saveSettingAsync(WORKSPACES_KEY, normalizedWorkspaces),
                    saveSettingAsync(ACTIVE_WORKSPACE_KEY, activeWorkspace)
                ]);

                let finalCards: Card[] = migratedCards;

                if (finalCards.length === 0) {
                    finalCards = buildWorkspaceSeedCards(activeWorkspace, INITIAL_LOAD_SEED_COUNT);
                    await saveCardsAsync(finalCards);
                }

                setCards(finalCards, true);
            } catch (e) {
            } finally {
                setIsLoading(false);
            }
        };
        loadData();
    }, [setIsLoading, setCards]);

    // Use a ref to ensure this only runs once
    const hasInitializedSearchRef = useRef(false);

    // Build embeddings & learn abbreviations
    useEffect(() => {
        if (cards.length > 0 && !hasInitializedSearchRef.current) {
            hasInitializedSearchRef.current = true;

            import('../learnedAbbreviations').then(({ learnFromCards, getLearnedAbbreviations }) => {
                learnFromCards(cards);
                if (window.electronAPI?.saveAbbreviations) {
                    window.electronAPI.saveAbbreviations(getLearnedAbbreviations());
                }
            });

            // Rebuild FlexSearch index on initial load
            rebuildIndex(cards);

            if (semanticReady) {
                setEmbeddingsReady(false);
                buildCardEmbeddings(cards)
                    .then(() => setEmbeddingsReady(true))
                    .catch(console.error);
            }
        }
    }, [cards, semanticReady]);

    // Note: saveCardsAsync is called explicitly in each store action (handleSaveCard,
    // confirmDelete, handleBatchImport, handleSuppressConnections). No effect needed here.

    return { semanticReady, embeddingsReady };
}

import { useLocation } from 'react-router-dom';
import { useUIStore } from '../store/useUIStore';
import type { AppSection } from '../types';

export function useCurrentSection(): AppSection {
    const location = useLocation();
    const path = location.pathname;

    if (path === '/') return 'dashboard';
    if (path.startsWith('/courses')) return 'courses';
    if (path.startsWith('/cards') || path.startsWith('/browse')) return 'cards';
    if (path.startsWith('/network')) return 'network';
    if (path.startsWith('/review')) return 'review';
    if (path.startsWith('/stats')) return 'stats';
    if (path.startsWith('/settings')) return 'settings';
    if (path.startsWith('/add')) return 'add';

    return 'dashboard'; // fallback
}

