import { useState, useEffect, useMemo } from 'react';
import type { Card } from '../types';
import { hybridSearch } from '../searchIndex';
import { calculateQualityScore } from '../algorithms/qualityScoring';
import { useDebounce } from './useDebounce';

export function useFilteredCards(cards: Card[], searchQuery: string, activeFilters: string[]) {
  const debouncedSearchQuery = useDebounce(searchQuery, 300);
  const [searchResultIds, setSearchResultIds] = useState<string[] | null>(null);

  const [isSearching, setIsSearching] = useState(false);

  // Reset results immediately when the query changes (replaces the illegal
  // synchronous setState-during-render pattern that was here before).
  useEffect(() => {
    setSearchResultIds(null);
    if (debouncedSearchQuery) {
        setIsSearching(true);
    }
  }, [debouncedSearchQuery]);

  // Async search: runs after the reset above has committed.
  useEffect(() => {
    if (!debouncedSearchQuery) return;

    let isActive = true;
    setIsSearching(true);
    hybridSearch(debouncedSearchQuery).then(res => {
        if (isActive) {
            setSearchResultIds(res);
            setIsSearching(false);
        }
    });

    return () => {
        isActive = false;
    };
  }, [debouncedSearchQuery]);

  const filteredCards = useMemo(() => {
    // 1. Type filter / Quality Filter
    let result = cards;
    if (activeFilters.length > 0) {
      if (activeFilters.includes('needs-review')) {
        // Quality Filter
        result = result.filter(card => {
          if (card.nodeType === 'course') return false;
          const score = calculateQualityScore(card, card.manualConnections?.length || 0);
          return score.score < 50;
        });
      } else {
        // Standard Type Filter (still filters by the subject tag: drug, patho, etc.)
        result = result.filter(card => activeFilters.includes(card.type) && card.nodeType !== 'course');
      }
    } else {
      // Exclude courses from the main cards view by default
      result = result.filter(card => card.nodeType !== 'course');
    }

    // 2. Search filter using hybrid (FlexSearch + semantic)
    if (searchResultIds !== null) {
      const idSet = new Set(searchResultIds);

      // Filter to only matching IDs and maintain search order (relevance)
      const idToCard = new Map(result.map(c => [c.id, c]));
      result = searchResultIds
        .filter(id => idSet.has(id) && idToCard.has(id))
        .map(id => idToCard.get(id)!)
        .filter(c => (activeFilters.length === 0 || activeFilters.includes(c.type)) && c.nodeType !== 'course');
    }

    return result;
  }, [cards, searchResultIds, activeFilters]);

  return { filteredCards, searchResultIds, isSearching };
}

import { useEffect } from 'react';
import {
    collection,
    onSnapshot,
    doc,
    getDocs,
    writeBatch,
} from 'firebase/firestore';
import { db, prepareForFirebase } from '../lib/firebase';
import { useCardStore } from '../store/useCardStore';
import { useAuth } from '../context/AuthContext';
import type { Card } from '../types';

import { toast } from '../store/useToastStore';
import { useUIStore } from '../store/useUIStore';

// Simple toast tracking shown only once per session
let migrationToastShown = false;
let lastMigrationUid: string | null = null;

export const useFirebaseSync = () => {
    const { user, loading } = useAuth();
    const { setCards } = useCardStore();

    useEffect(() => {
        if (loading) return;
        if (!user) return;

        const userCardsRef = collection(db, `users/${user.uid}/cards`);

        const syncInitial = async () => {
            useUIStore.getState().setSyncStatus('pending');
            try {
                const snapshot = await getDocs(userCardsRef);
                const remoteCards: Record<string, Card> = {};
                snapshot.forEach(d => { remoteCards[d.id] = d.data() as Card; });

                const localCards = useCardStore.getState().cards;
                const mergedCards = [...localCards];
                let hasLocalChanges = false;
                const batch = writeBatch(db);
                let batchCount = 0;

                // ── Migrate offline cards (ownerUid === null) ──────────────
                // A-4 fix: reset migrationToastShown when user changes
                if (lastMigrationUid !== user.uid) {
                    migrationToastShown = false;
                    lastMigrationUid = user.uid;
                }

                const offlineCards = localCards.filter(c => c.ownerUid === null || c.ownerUid === undefined);
                const migratedCount = 0;

                if (offlineCards.length > 0 && !sessionStorage.getItem('extnd_ignore_offline')) {
                    useUIStore.getState().setPendingOfflineCards(offlineCards);
                }

                // ── Push local cards newer than remote ────────────────────
                for (const localCard of localCards) {
                    if (localCard.ownerUid === null || localCard.ownerUid === undefined) continue; // already handled above
                    if (!remoteCards[localCard.id]) {
                        const cardRef = doc(db, `users/${user.uid}/cards`, localCard.id);
                        batch.set(cardRef, prepareForFirebase(localCard));
                        batchCount++;
                    } else if ((localCard.updatedAt || 0) > (remoteCards[localCard.id].updatedAt || 0)) {
                        const cardRef = doc(db, `users/${user.uid}/cards`, localCard.id);
                        batch.set(cardRef, prepareForFirebase(localCard));
                        batchCount++;
                    }
                }

                if (batchCount > 0) await batch.commit();
                if (migratedCount > 0 && !migrationToastShown) {
                    migrationToastShown = true;
                    toast.success(`✓ ${migratedCount} fiche${migratedCount > 1 ? 's' : ''} hors-ligne migrée${migratedCount > 1 ? 's' : ''} vers votre compte.`);
                }

                let conflictsCount = 0;

                // ── Pull remote cards into local ──────────────────────────
                for (const [id, remoteCard] of Object.entries(remoteCards)) {
                    const localIndex = mergedCards.findIndex(c => c.id === id);
                    if (localIndex === -1) {
                        mergedCards.push(remoteCard);
                        hasLocalChanges = true;
                    } else if ((remoteCard.updatedAt || 0) > (mergedCards[localIndex].updatedAt || 0)) {
                        mergedCards[localIndex] = remoteCard;
                        hasLocalChanges = true;
                        conflictsCount++;
                    }
                }

                if (conflictsCount > 0) {
                    toast.info(`Une version plus récente a été restaurée depuis le serveur (${conflictsCount} fiche${conflictsCount > 1 ? 's' : ''}).`);
                }

                if (hasLocalChanges) {
                    setCards(mergedCards, false);
                }
                useUIStore.getState().setSyncStatus('synced');
            } catch (error) {
                useUIStore.getState().setSyncStatus('error');
                toast.error('Erreur de synchronisation Firebase', 0, {
                    label: 'Réessayer',
                    onClick: () => {
                        syncInitial();
                    }
                });
            }
        };

        let unsubscribe: (() => void) | undefined;

        const initAndListen = async () => {
            await syncInitial();

            // ── Real-time listener ────────────────────────────────────────────
            unsubscribe = onSnapshot(userCardsRef, (snapshot) => {
                snapshot.docChanges().forEach((change) => {
                    const data = change.doc.data() as Card;
                    const currentCards = useCardStore.getState().cards;

                    if (change.type === 'added' || change.type === 'modified') {
                        const existsIndex = currentCards.findIndex(c => c.id === data.id);
                        if (existsIndex >= 0) {
                            if ((data.updatedAt || 0) > (currentCards[existsIndex].updatedAt || 0)) {
                                const newCards = [...currentCards];
                                newCards[existsIndex] = data;
                                // C-3 fix: skipSave=true — Firebase is the source of truth here,
                                // saving back to IndexedDB would cause a write→snapshot→write loop.
                                setCards(newCards, true);
                                toast.info('Une version plus récente a été restaurée depuis le serveur.');
                            }
                        } else {
                            setCards([...currentCards, data], true); // C-3 fix: skipSave=true
                        }
                    }
                    if (change.type === 'removed') {
                        setCards(currentCards.filter(c => c.id !== data.id), true); // C-3 fix: skipSave=true
                    }
                });
            });
        };

        initAndListen();

        return () => {
            if (unsubscribe) unsubscribe();
        };
    }, [user, loading, setCards]);
};

import { useEffect } from 'react';
import { useUIStore as useUI } from '../store/useUIStore';
import type { AppSection } from '../types';

interface UseGlobalShortcutsOptions {
    isNetworkContext: boolean;
    networkPanelPinned: boolean;
    setSelectedCardId: (id: string | null) => void;
    navigateSection: (section: AppSection) => void;
}

export function useGlobalShortcuts({
    isNetworkContext,
    networkPanelPinned,
    setSelectedCardId,
    navigateSection
}: UseGlobalShortcutsOptions) {
    const { setOmniboxOpen, sidebarOpen, setSidebarOpen, setAddDataMode } = useUI();

    useEffect(() => {
        const onKeyDown = (event: KeyboardEvent) => {
            if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') {
                event.preventDefault();
                setOmniboxOpen(true);
            }
            if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'n') {
                event.preventDefault();
                setAddDataMode('create');
            }
            if (event.key === 'Escape' && sidebarOpen) {
                setSidebarOpen(false);
                return;
            }
            if (event.key === 'Escape' && isNetworkContext && !networkPanelPinned) {
                setSelectedCardId(null);
            }
            if (event.altKey && ['1', '2', '3', '4', '5'].includes(event.key)) {
                event.preventDefault();
                const mapping: Record<string, AppSection> = {
                    '1': 'dashboard',
                    '2': 'cards',
                    '3': 'network',
                    '4': 'review',
                    '5': 'settings'
                };
                navigateSection(mapping[event.key]);
            }
        };
        window.addEventListener('keydown', onKeyDown);
        return () => window.removeEventListener('keydown', onKeyDown);
    }, [isNetworkContext, networkPanelPinned, navigateSection, sidebarOpen, setOmniboxOpen, setSidebarOpen, setSelectedCardId]);
}

import { useState, useEffect, useRef } from 'react';
import type { Card, Node, Link } from '../types';
import { computePrecisionGraph } from '../semanticSearch';

// We need to import the worker constructor. 
// Vite handles 'new Worker(new URL(...))' automatically.

export interface GraphData {
    nodes: Node[];
    links: Link[];
}

export interface UseGraphDataProps {
    cards: Card[];
    vetoPairs?: string[];
    semanticReady?: boolean; // Signal if we should wait for semantic search or not (optional)
    typeCompat?: Record<string, number>;
}

export function useGraphData({ cards, vetoPairs = [], semanticReady = false, typeCompat = {} }: UseGraphDataProps) {
    const [graphData, setGraphData] = useState<GraphData>({ nodes: [], links: [] });
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    // Worker ref to keep the instance
    const workerRef = useRef<Worker | null>(null);

    // State to hold latest results from both sources
    const [lexicalResult, setLexicalResult] = useState<GraphData | null>(null);
    const [semanticLinks, setSemanticLinks] = useState<Link[]>([]);

    useEffect(() => {
        // Initialize worker if not exists
        if (!workerRef.current) {
            workerRef.current = new Worker(new URL('../workers/graph.worker.ts', import.meta.url), {
                type: 'module'
            });

            workerRef.current.onmessage = (e: MessageEvent<GraphData>) => {
                const { nodes, links } = e.data;
                setLexicalResult({ nodes, links });
                setError(null);
            };

            workerRef.current.onerror = (err) => {
                setError('Erreur de génération du graphe. Réessayez dans quelques secondes.');
                setIsLoading(false);
            };
        }

        // Cleanup
        return () => {
            if (workerRef.current) {
                workerRef.current.terminate();
                workerRef.current = null;
            }
        };
    }, []);

    // Send data to worker when cards or vetoPairs change
    useEffect(() => {
        if (!workerRef.current || cards.length === 0) return;

        setIsLoading(true);
        setError(null);

        // Prepare payload matching WorkerInput interface
        const payload = {
            cards,
            feedback: {
                vetoPairs,
                typePairScores: typeCompat,
                negativePatterns: [],
                positivePatterns: [],
                toxicKeywords: {}
            }
        };

        workerRef.current.postMessage(payload);
    }, [cards, vetoPairs, typeCompat]);

    // Compute Semantic Links when ready
    useEffect(() => {
        if (cards.length === 0 || !semanticReady) {
            if (!semanticReady) setSemanticLinks([]); // Clear if not ready
            return;
        }


        computePrecisionGraph(cards, vetoPairs, typeCompat)
            .then(links => {
                // Map to Link type
                const formattedLinks: Link[] = links.map(l => ({
                    source: l.source,
                    target: l.target,
                    value: l.value,
                    type: l.type,
                    reason: l.reason,
                    quality: 'match' // Default quality for semantic
                }));
                setSemanticLinks(formattedLinks);
            })
            .catch(err => {
                setError('Erreur de calcul sémantique du graphe.');
            });

    }, [cards, vetoPairs, typeCompat, semanticReady]);

    // Merge Results
    useEffect(() => {
        if (!lexicalResult) return;

        const { nodes, links: lexicalLinks } = lexicalResult;

        // Merge links (lexical + semantic)
        // Deduplicate: If link exists in both, prefer Semantic? Or Lexical?
        // Semantic links are usually higher quality ("High Precision").
        // Lexical are "Broad Recall".

        const mergedLinks = [...lexicalLinks];
        const existingKeys = new Set(lexicalLinks.map(l => {
            const s = typeof l.source === 'object' ? l.source.id : l.source;
            const t = typeof l.target === 'object' ? l.target.id : l.target;
            return [s, t].sort().join('-');
        }));

        let addedCount = 0;
        semanticLinks.forEach(l => {
            const key = [l.source, l.target].sort().join('-');
            if (!existingKeys.has(key)) {
                mergedLinks.push(l);
                existingKeys.add(key);
                addedCount++;
            }
        });


        setGraphData({ nodes, links: mergedLinks });
        setIsLoading(false);

    }, [lexicalResult, semanticLinks]);

    // We only expose loading state for the *initial* lexical build mostly
    // Semantic can stream in late.

    return { graphData, isLoading, error };
}

import { useCallback } from 'react';
import { useTheme } from '../context/ThemeContext';
import type { GraphNode, GraphLink } from '../components/NetworkGraphTypes';
import { linkEndpointId } from '../components/NetworkGraphTypes';

interface UseGraphPaintProps {
    hoverNode: GraphNode | null;
    hoverLink: GraphLink | null;
    selectedNodes: Set<string>;
    graphDataLinks: GraphLink[];
    searchHighlightIds: Set<string> | null;
    isDark: boolean;
    pendingClusterReview: boolean | undefined;
    nodeClusterMap: Map<string, string>;
    activeNodeId: string | null | undefined;
    pathLinks: Set<string>;
    getClusterColor: (clusterId: string) => string;
}

export function useGraphPaint({
    hoverNode,
    hoverLink,
    selectedNodes,
    graphDataLinks,
    searchHighlightIds,
    isDark,
    pendingClusterReview,
    nodeClusterMap,
    activeNodeId,
    pathLinks,
    getClusterColor
}: UseGraphPaintProps) {

    const { getCategoryColor } = useTheme();

    const nodePaint = useCallback((node: GraphNode, ctx: CanvasRenderingContext2D, globalScale: number) => {
        if (!Number.isFinite(node.x) || !Number.isFinite(node.y)) return;

        // Visual States
        const isHover = node === hoverNode;
        const isSelected = selectedNodes.has(node.id) || node.id === activeNodeId;

        let isDimmed = false;

        if (hoverNode) {
            const isNeighbor = graphDataLinks.some(link => {
                const src = linkEndpointId(link.source as GraphLink['source']);
                const tgt = linkEndpointId(link.target as GraphLink['target']);
                return (src === hoverNode.id && tgt === node.id) || (tgt === hoverNode.id && src === node.id);
            });
            if (!isHover && !isNeighbor) isDimmed = true;
        } else if (activeNodeId) {
            const isNeighbor = graphDataLinks.some(link => {
                const src = linkEndpointId(link.source as GraphLink['source']);
                const tgt = linkEndpointId(link.target as GraphLink['target']);
                return (src === activeNodeId && tgt === node.id) || (tgt === activeNodeId && src === node.id);
            });
            if (node.id !== activeNodeId && !isNeighbor) isDimmed = true;
        } else if (searchHighlightIds) {
            if (!searchHighlightIds.has(node.id)) isDimmed = true;
        }

        ctx.save();

        if (isDimmed) {
            ctx.globalAlpha = 0.06; // Very faint for non-relevant nodes
        }

        const label = node.name;

        // Use cluster for color if available, fallback to type
        let color = getCategoryColor(node.type);
        if (pendingClusterReview) {
            const clusterId = nodeClusterMap.get(node.id);
            if (clusterId) {
                color = getClusterColor(clusterId);
            } else {
                color = isDark ? '#334155' : '#e2e8f0'; // Gray out nodes not in any cluster
            }
        } else if (node.cluster !== undefined && node.cluster >= 0) {
            // Generate a vibrant color based on cluster ID (legacy graph clustering)
            const hue = (node.cluster * 137.508) % 360;
            color = `hsl(${hue}, 70%, ${isDark ? '60%' : '45%'})`;
        }

        const radius = Math.max(2, Math.min(node.val || 2, 8));

        // Selection Halo
        if (isHover || isSelected) {
            ctx.beginPath();
            ctx.arc(node.x as number, node.y as number, radius + 4, 0, 2 * Math.PI, false);
            ctx.fillStyle = isSelected ? 'rgba(59, 130, 246, 0.25)' : (isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0, 0, 0, 0.08)');
            ctx.fill();
            ctx.strokeStyle = isSelected ? 'var(--color-physio)' : color;
            ctx.lineWidth = 2 / globalScale;
            ctx.stroke();
        }

        // Node Body
        ctx.beginPath();
        ctx.arc(node.x as number, node.y as number, radius, 0, 2 * Math.PI, false);
        ctx.fillStyle = color;
        ctx.fill();

        // Text Visibility Logic
        // 1. Hover/Selected: ALWAYS show.
        // 2. Search Active: Only show if Highlighted AND zoomed in closer than global view.
        // 3. Normal: Show if zoomed in.
        let showText = false;

        if (isHover || isSelected) {
            showText = true;
        } else if (searchHighlightIds) {
            if (searchHighlightIds.has(node.id) && globalScale > 0.8) {
                showText = true;
            }
        } else {
            if (globalScale > 2.0 && !isDimmed) {
                showText = true;
            }
        }

        if (showText) {
            const fontSize = 12 / globalScale;
            ctx.font = `600 ${fontSize}px Inter, Sans-Serif`;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';

            // Stroke for readability (use bg color as outline)
            ctx.strokeStyle = isDark ? '#0f172a' : '#ffffff';
            ctx.lineWidth = 3 / globalScale;
            ctx.strokeText(label, node.x as number, (node.y as number) + radius + 6);

            ctx.fillStyle = isDark ? '#f8fafc' : '#0f172a';
            ctx.fillText(label, node.x as number, (node.y as number) + radius + 6);
        }

        ctx.restore();
    }, [hoverNode, selectedNodes, graphDataLinks, searchHighlightIds, isDark, pendingClusterReview, nodeClusterMap, activeNodeId, getClusterColor, getCategoryColor]);

    const linkPaint = useCallback((link: GraphLink, ctx: CanvasRenderingContext2D, globalScale: number) => {
        const source = link.source;
        const target = link.target;

        if (typeof source === 'string' || typeof target === 'string') return;
        if (!Number.isFinite(source.x) || !Number.isFinite(source.y) ||
            !Number.isFinite(target.x) || !Number.isFinite(target.y)) return;

        const isHover = (hoverNode && (source.id === hoverNode.id || target.id === hoverNode.id)) || (hoverLink === link);
        const linkKey = [source.id, target.id].sort().join('-');
        const isPath = pathLinks.has(linkKey);

        let isDimmed = false;
        if (hoverNode) {
            if (!isHover) isDimmed = true;
        } else if (activeNodeId) {
            if (source.id !== activeNodeId && target.id !== activeNodeId) isDimmed = true;
        } else if (searchHighlightIds) {
            if (!searchHighlightIds.has(source.id) || !searchHighlightIds.has(target.id)) isDimmed = true;
        }
        if (isPath) isDimmed = false;

        if (isDimmed) {
            ctx.globalAlpha = 0.05;
        } else if (isPath || isHover) {
            ctx.globalAlpha = 1;
        } else {
            ctx.globalAlpha = 0.4;
        }

        ctx.beginPath();
        ctx.moveTo(source.x as number, source.y as number);
        ctx.lineTo(target.x as number, target.y as number);

        const useGradient = globalScale > 0.8 || isHover; // isPath is handled above

        if (useGradient) {
            const gradient = ctx.createLinearGradient(source.x as number, source.y as number, target.x as number, target.y as number);
            gradient.addColorStop(0, getCategoryColor(source.type));
            gradient.addColorStop(1, getCategoryColor(target.type));
            ctx.strokeStyle = gradient;
            ctx.lineWidth = (isHover ? 2.5 : 1) / globalScale;
            ctx.shadowBlur = 0;
            ctx.setLineDash([]);
        } else {
            ctx.strokeStyle = getCategoryColor(source.type);
            ctx.lineWidth = 1 / globalScale;
            ctx.shadowBlur = 0;
            ctx.setLineDash([]);
        }

        const isManual = source.manualConnections?.includes(target.id) || target.manualConnections?.includes(source.id);

        if (!isManual) { // isPath is handled above
            ctx.setLineDash([3 / globalScale, 3 / globalScale]);
        } else {
            ctx.setLineDash([]);
        }

        ctx.stroke();

        // Draw biological directional arrows
        const isStimulates = link.type === 'stimulates';
        const isInhibits = link.type === 'inhibits';

        if (isStimulates || isInhibits) {
            const angle = Math.atan2((target.y as number) - (source.y as number), (target.x as number) - (source.x as number));
            const targetRadius = Math.max(2, Math.min(target.val || 2, 8));

            // Position arrow just outside the node radius
            const arrowX = (target.x as number) - Math.cos(angle) * (targetRadius + 2 / globalScale);
            const arrowY = (target.y as number) - Math.sin(angle) * (targetRadius + 2 / globalScale);

            ctx.beginPath();

            if (isStimulates) {
                const ARROW_LENGTH = 6 / globalScale;
                ctx.moveTo(arrowX, arrowY);
                ctx.lineTo(arrowX - ARROW_LENGTH * Math.cos(angle - Math.PI / 6), arrowY - ARROW_LENGTH * Math.sin(angle - Math.PI / 6));
                ctx.lineTo(arrowX - ARROW_LENGTH * Math.cos(angle + Math.PI / 6), arrowY - ARROW_LENGTH * Math.sin(angle + Math.PI / 6));
                ctx.closePath();
                ctx.fillStyle = '#10b981'; // Green for stimulates
                ctx.fill();
            } else if (isInhibits) {
                const BAR_WIDTH = 5 / globalScale;
                ctx.moveTo(arrowX - BAR_WIDTH * Math.cos(angle - Math.PI / 2), arrowY - BAR_WIDTH * Math.sin(angle - Math.PI / 2));
                ctx.lineTo(arrowX - BAR_WIDTH * Math.cos(angle + Math.PI / 2), arrowY - BAR_WIDTH * Math.sin(angle + Math.PI / 2));
                ctx.strokeStyle = '#ef4444'; // Red for inhibits
                ctx.lineWidth = 2.5 / globalScale;
                ctx.stroke();
            }
        }

        // Reset Context
        ctx.globalAlpha = 1;
        ctx.shadowBlur = 0;
        ctx.setLineDash([]);

    }, [hoverNode, hoverLink, pathLinks, searchHighlightIds, isDark, activeNodeId, getCategoryColor]);

    return { nodePaint, linkPaint };
}

import { useMemo } from 'react';
import type { GraphLink } from '../components/NetworkGraphTypes';
import { linkEndpointId } from '../components/NetworkGraphTypes';

interface UseNetworkFiltersProps {
    graphData: { nodes: any[], links: any[] };
    activeFilters: string[] | undefined;
    searchQuery: string | undefined;
    highlightedIds: Set<string> | undefined;
    searchDepth: number;
}

export function useNetworkFilters({
    graphData,
    activeFilters,
    searchQuery,
    highlightedIds,
    searchDepth
}: UseNetworkFiltersProps) {

    // 1. Structural Filter: Removes nodes entirely (e.g. by Category)
    const structuralData = useMemo(() => {
        let nodes = graphData.nodes;
        let links = graphData.links;

        // Apply Category Filters (Strict)
        if (activeFilters && activeFilters.length > 0) {
            // Filter out special UI-only filters like 'needs-review' or 'all'
            const realTypeFilters = activeFilters.filter(f => f !== 'needs-review' && f !== 'all');

            if (realTypeFilters.length > 0) {
                const allowedTypes = new Set(realTypeFilters);
                const keepIds = new Set<string>();
                nodes = nodes.filter(n => {
                    if (allowedTypes.has(n.type)) {
                        keepIds.add(n.id);
                        return true;
                    }
                    return false;
                });
                links = links.filter(l => {
                    const src = linkEndpointId(l.source as GraphLink['source']);
                    const tgt = linkEndpointId(l.target as GraphLink['target']);
                    return keepIds.has(src) && keepIds.has(tgt);
                });
            }
        }

        // Also apply local suppression filter if not caught by worker yet
        links = links.filter(() => {
            return true;
        });

        return { nodes, links };
    }, [graphData, activeFilters]);

    // 2. Visual Highlight: Determines what is "Dimmed" based on Search
    const searchHighlightIds = useMemo(() => {
        if (!searchQuery && (!highlightedIds || highlightedIds.size === 0)) return null; // No active search highlight

        // Find matches
        const matches = new Set<string>();
        structuralData.nodes.forEach(n => {
            if (searchQuery && n.name.toLowerCase().includes(searchQuery.toLowerCase())) matches.add(n.id);
            if (highlightedIds && highlightedIds.has(n.id)) matches.add(n.id);
        });

        if (matches.size === 0) return new Set<string>();

        // Expand by Depth
        let currentLayer = new Set(matches);
        const accumulated = new Set(matches);

        for (let d = 0; d < searchDepth; d++) {
            const nextLayer = new Set<string>();
            structuralData.links.forEach(l => {
                const src = linkEndpointId(l.source as GraphLink['source']);
                const tgt = linkEndpointId(l.target as GraphLink['target']);

                if (currentLayer.has(src) && !accumulated.has(tgt)) {
                    nextLayer.add(tgt);
                    accumulated.add(tgt);
                }
                if (currentLayer.has(tgt) && !accumulated.has(src)) {
                    nextLayer.add(src);
                    accumulated.add(src);
                }
            });
            currentLayer = nextLayer;
            if (currentLayer.size === 0) break;
        }

        return accumulated;
    }, [structuralData, searchQuery, highlightedIds, searchDepth]);

    return { structuralData, searchHighlightIds };
}

import { useState, useMemo, useCallback } from 'react';
import type { Card } from '../types';
import { useUIStore } from '../store/useUIStore';
import { auth } from '../lib/firebase';
import { loadSrsSettings } from '../components/settings/RevisionTab';

export function useReviewSession(cards: Card[]) {
    // Removed setActiveSection from useUIStore
    const [reviewSession, setReviewSession] = useState<{ cardIds: string[]; title: string; initialIndex?: number } | null>(null);

    const reviewSessionCards = useMemo(() => {
        if (!reviewSession) return [];
        const idSet = new Set(reviewSession.cardIds);
        const currentUid = auth.currentUser?.uid ?? null;
        return cards.filter((card) => {
            if (!idSet.has(card.id)) return false;
            // M-5 fix: only include cards owned by the current user or offline cards (ownerUid === null)
            if (currentUid && card.ownerUid && card.ownerUid !== currentUid) return false;
            return true;
        });
    }, [cards, reviewSession]);


    const startFSRSReview = useCallback((tags?: string[]) => {
        const now = Date.now();
        let dueCards = cards.filter((card) => {
            const dueDate = card.progress?.dueDate ? new Date(card.progress.dueDate).getTime() : 0;
            if (!card.progress) return false;
            if (card.progress.status === 'learning' || card.progress.status === 'review') {
                return dueDate <= now;
            }
            return false;
        });

        // [F-A] Inclure les nouvelles cartes
        let newCards = cards.filter((card) => {
            return !card.progress || card.progress.status === 'new';
        });

        if (tags && tags.length > 0) {
            dueCards = dueCards.filter(c => c.tags && c.tags.some(t => tags.includes(t)));
            newCards = newCards.filter(c => c.tags && c.tags.some(t => tags.includes(t)));
        }

        const srsSettings = loadSrsSettings();
        const maxNewCards = srsSettings.maxNewCardsPerSession || 10;
        // Prendre un maximum de nouvelles cartes par session pour ne pas surcharger l'utilisateur
        const selectedNewCards = newCards.slice(0, maxNewCards);

        // Interleave due and new cards for better learning (random shuffle)
        const finalCards = [...dueCards, ...selectedNewCards].sort(() => 0.5 - Math.random());

        // Si vraiment aucune carte n'est due ni nouvelle, on fallback sur une session de découverte (flashcards en priorité)
        const fallback = finalCards.length > 0 
            ? finalCards 
            : cards.filter(c => c.nodeType === 'flashcard').slice(0, 20);

        setReviewSession({
            cardIds: fallback.map((c) => c.id),
            title: finalCards.length > 0 ? (tags && tags.length > 0 ? `Révision planifiée (${tags.join(', ')})` : 'Révision planifiée (FSRS)') : 'Session découverte',
        });
    }, [cards]);

    const startIntensiveReview = useCallback(() => {
        // Shuffle all workspace cards
        const shuffled = [...cards].sort(() => 0.5 - Math.random());
        const selected = shuffled.slice(0, Math.min(30, shuffled.length));
        setReviewSession({
            cardIds: selected.map((c) => c.id),
            title: 'Bachotage Intensif',
        });
    }, [cards]);

    const startCourseReview = useCallback((courseId: string, title: string) => {
        const flashcards = cards.filter(c => c.nodeType === 'flashcard' && c.parentId === courseId);
        if (flashcards.length === 0) return;
        // Prioritize due cards first, then new ones
        const shuffled = [...flashcards].sort((a, b) => {
            const dueA = a.progress?.dueDate ? new Date(a.progress.dueDate).getTime() : Infinity;
            const dueB = b.progress?.dueDate ? new Date(b.progress.dueDate).getTime() : Infinity;
            return dueA - dueB;
        });
        setReviewSession({
            cardIds: shuffled.map(c => c.id),
            title,
        });
    }, [cards]);


    const startCustomReview = useCallback((config: { tags: string[]; types: string[]; statuses: string[]; limit: number | null }) => {
        let flashcards = cards.filter(c => c.nodeType === 'flashcard');

        // Filter by types
        if (config.types.length > 0) {
            flashcards = flashcards.filter(c => config.types.includes(c.type));
        }

        // Filter by tags
        if (config.tags.length > 0) {
            // Must have at least one of the tags
            flashcards = flashcards.filter(c => c.tags && c.tags.some(t => config.tags.includes(t)));
        }

        // Filter by status
        if (config.statuses.length > 0) {
            flashcards = flashcards.filter(c => {
                const status = c.progress?.status || 'new';
                return config.statuses.includes(status);
            });
        }

        // Shuffle
        let shuffled = [...flashcards].sort(() => 0.5 - Math.random());

        // Apply limit
        if (config.limit !== null && config.limit > 0) {
            shuffled = shuffled.slice(0, config.limit);
        }

        if (shuffled.length === 0) return;

        setReviewSession({
            cardIds: shuffled.map(c => c.id),
            title: 'Deck Personnalisé',
        });
    }, [cards]);

    const startQuizReview = useCallback(() => {
        // Pick 10 random flashcards, prioritizing due/learning ones
        const flashcards = cards.filter(c => c.nodeType === 'flashcard');
        const due = flashcards.filter(c => c.progress?.status === 'review' || c.progress?.status === 'learning');
        const pool = due.length >= 10 ? due : [...due, ...flashcards.filter(c => !due.includes(c))];
        const shuffled = [...pool].sort(() => 0.5 - Math.random()).slice(0, 10);
        setReviewSession({
            cardIds: shuffled.map(c => c.id),
            title: 'Quiz Express',
        });
    }, [cards]);

    return {
        reviewSession,
        setReviewSession,
        reviewSessionCards,
        startFSRSReview,
        startIntensiveReview,
        startCourseReview,
        startQuizReview,
        startCustomReview,
    };
}

import { initializeApp } from "firebase/app";
