export interface FTSResult {
    id: string;
    highlight: string;
}

/**
 * Fast Lexical Search using SQLite FTS5.
 * Returns both the ID and a highlighted snippet of the match.
 */
export async function fastLexicalSearch(query: string, limit = 50): Promise<FTSResult[]> {
    if (!query.trim()) return [];

    if (window.electronAPI?.searchCardsFTS) {
        try {
            return await window.electronAPI.searchCardsFTS(query, limit);
        } catch (e) {
            return [];
        }
    }
    return [];
}

/**
 * Hybrid search: combines FTS5 (Lexical) and semantic search (Voy-search).
 * Also expands medical abbreviations (DT1 -> Diabete type 1, HTA -> Hypertension, etc.)
 */
export async function hybridSearch(query: string, limit = 50): Promise<string[]> {
    if (!query.trim()) return [];

    // Expand medical abbreviations to get all search variants
    const queryVariants = expandMedicalQuery(query);

    // Get keyword results for all variants via FTS5
    const keywordResults: string[] = [];
    const seenKeyword = new Set<string>();

    for (const variant of queryVariants) {
        const results = await fastLexicalSearch(variant, limit);
        for (const res of results) {
            if (!seenKeyword.has(res.id)) {
                keywordResults.push(res.id);
                seenKeyword.add(res.id);
            }
        }
    }

    // If semantic search is not ready or query is too short, return keyword only
    if (!isSemanticSearchReady() || query.length < 2) {
        return keywordResults.slice(0, limit);
    }

    try {
        // Get semantic results for all query variants (async parallel)
        const semanticPromises = queryVariants.map(variant => semanticSearch(variant, limit));
        const resultsArrays = await Promise.all(semanticPromises);

        const semanticResultsAll: string[] = [];
        const seenSemantic = new Set<string>();

        // Flatten results while maintaining unique set
        resultsArrays.flat().forEach(id => {
            if (!seenSemantic.has(id)) {
                semanticResultsAll.push(id);
                seenSemantic.add(id);
            }
        });

        // Compute RRF scores
        const scores = new Map<string, number>();
        const k = 60; // RRF constant

        // Score keyword results
        keywordResults.forEach((id, rank) => {
            const score = 1 / (k + rank + 1);
            scores.set(id, (scores.get(id) || 0) + score);
        });

        // Score semantic results
        semanticResultsAll.forEach((id, rank) => {
            const score = 1 / (k + rank + 1);
            scores.set(id, (scores.get(id) || 0) + score);
        });

        // Sort by score DESC
        const sortedIds = Array.from(scores.entries())
            .sort((a, b) => b[1] - a[1])
            .map(([id]) => id);

        return sortedIds.slice(0, limit);
    } catch (error) {
        return keywordResults.slice(0, limit);
    }
}

import { doc, deleteDoc, runTransaction } from 'firebase/firestore';
import { auth, db, prepareForFirebase } from '../lib/firebase';
import type { Card } from '../types';
import { syncQueue } from './syncQueue';

export const cardSyncService = {
  // Public methods just enqueue the tasks
  saveCard: (card: Card): void => {
    if (!auth.currentUser) return;
    syncQueue.enqueueSaveCard(card);
  },

  deleteCard: (cardId: string): void => {
    if (!auth.currentUser) return;
    syncQueue.enqueueDeleteCard(cardId);
  },

  // Internal methods used by SyncQueue to actually perform the operations
  performSaveCard: async (card: Card): Promise<void> => {
    if (!auth.currentUser) return;

    const cardRef = doc(db, `users/${auth.currentUser.uid}/cards`, card.id);
    const sanitized = prepareForFirebase(card);

    // Avertissement taille document (limite Firestore = 1 Mo)
    const sizeBytes = new Blob([JSON.stringify(sanitized)]).size;
    if (sizeBytes > 750_000) {
    }

    // Use transaction to ensure we don't overwrite a newer server version
    await runTransaction(db, async (transaction) => {
      const docSnap = await transaction.get(cardRef);
      if (docSnap.exists()) {
        const serverData = docSnap.data();
        if (serverData.updatedAt && card.updatedAt && serverData.updatedAt > card.updatedAt) {
          // Server has a more recent version, we reject this local save
          throw new Error("CONFLICT_SERVER_NEWER");
        }
      }
      transaction.set(cardRef, sanitized);
    });
  },

  performDeleteCard: async (cardId: string): Promise<void> => {
    if (!auth.currentUser) return;
    const cardRef = doc(db, `users/${auth.currentUser.uid}/cards`, cardId);
    await deleteDoc(cardRef);
  }
};

import type { LlmConfig } from '../types';

export interface ChatMessage {
  role: 'system' | 'user' | 'assistant';
  content: string;
}

export async function streamLLMResponse(
  messages: ChatMessage[],
  config: LlmConfig,
  onChunk: (chunk: string) => void
): Promise<void> {
  if (!config.apiKey) {
    throw new Error('Clé API manquante. Veuillez configurer PharmaBot dans les paramètres.');
  }

  if (config.provider === 'openai') {
    await streamOpenAI(messages, config.apiKey, onChunk);
  } else if (config.provider === 'gemini') {
    await streamGemini(messages, config.apiKey, onChunk);
  } else {
    throw new Error('Fournisseur IA non supporté.');
  }
}

async function streamOpenAI(messages: ChatMessage[], apiKey: string, onChunk: (chunk: string) => void) {
  const response = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${apiKey}`
    },
    body: JSON.stringify({
      model: 'gpt-4o-mini', // Can be configurable later
      messages,
      stream: true,
    })
  });

  if (!response.ok) {
    const error = await response.json().catch(() => ({}));
    throw new Error(`OpenAI API Error: ${error.error?.message || response.statusText}`);
  }

  if (!response.body) throw new Error('No response body');

  const reader = response.body.getReader();
  const decoder = new TextDecoder('utf-8');

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;

    const chunk = decoder.decode(value, { stream: true });
    const lines = chunk.split('\n').filter(line => line.trim() !== '');

    for (const line of lines) {
      if (line === 'data: [DONE]') return;
      if (line.startsWith('data: ')) {
        try {
          const data = JSON.parse(line.slice(6));
          if (data.choices && data.choices[0].delta?.content) {
            onChunk(data.choices[0].delta.content);
          }
        } catch (e) {
          // ignore partial JSON
        }
      }
    }
  }
}

async function streamGemini(messages: ChatMessage[], apiKey: string, onChunk: (chunk: string) => void) {
  const systemMsg = messages.find(m => m.role === 'system');
  const userAndAssistantMsgs = messages.filter(m => m.role !== 'system');

  if (systemMsg && userAndAssistantMsgs.length > 0 && userAndAssistantMsgs[0].role === 'user') {
    userAndAssistantMsgs[0] = {
      ...userAndAssistantMsgs[0],
      content: systemMsg.content + "\n\n" + userAndAssistantMsgs[0].content
    };
  }

  const geminiMessages = userAndAssistantMsgs.map(msg => ({
    role: msg.role === 'assistant' ? 'model' : 'user',
    parts: [{ text: msg.content }]
  }));

  const payload: unknown = {
    contents: geminiMessages,
  };

  const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemma-4-31b-it:streamGenerateContent?alt=sse&key=${apiKey}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(payload)
  });

  if (!response.ok) {
    const error = await response.json().catch(() => ({}));
    throw new Error(`Gemini API Error: ${error.error?.message || response.statusText}`);
  }

  if (!response.body) throw new Error('No response body');

  const reader = response.body.getReader();
  const decoder = new TextDecoder('utf-8');

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;

    const chunk = decoder.decode(value, { stream: true });
    const lines = chunk.split('\n').filter(line => line.trim() !== '');

    for (const line of lines) {
      if (line.startsWith('data: ')) {
        try {
          const data = JSON.parse(line.slice(6));
          if (data.candidates && data.candidates[0].content?.parts) {
            const text = data.candidates[0].content.parts[0].text;
            if (text) {
                onChunk(text);
            }
          }
        } catch (e) {
          // ignore partial JSON
        }
      }
    }
  }
}

