/**
 * Locates the sql-wasm.wasm file in different environments:
 * - Web (Vite dev/prod): served from /
 * - Electron (file:// protocol): relative to window.location
 */
function getSqlWasmPath(file: string): string {
    // In Electron, window.location.href is like file:///path/to/dist/index.html
    // We need to serve the wasm file from the same directory
    if (typeof window !== 'undefined' && window.location.protocol === 'file:') {
        const base = window.location.href.replace(/[^/]+$/, '');
        return `${base}${file}`;
    }
    // Standard web: the wasm is at the root of the public folder
    return `/${file}`;
}

export async function exportToAnki(deckName: string, cards: Card[]): Promise<void> {
    if (!cards || cards.length === 0) {
        throw new Error("Aucune carte à exporter.");
    }

    // Initialize SQL.js — handles both web and Electron environments
    const SQL = await initSqlJs({
        locateFile: (file) => getSqlWasmPath(file)
    });

    const m = new Model({
        name: "SecondBrain Basic",
        id: "1543634829843",
        flds: [{ name: "Front" }, { name: "Back" }],
        req: [[0, "all", [0]]],
        tmpls: [{
            name: "Card 1",
            qfmt: "{{Front}}",
            afmt: "{{FrontSide}}\n\n<hr id=answer>\n\n{{Back}}"
        }]
    });

    const deckId = 1276438724672;
    const d = new Deck(deckId, deckName);

    for (const card of cards) {
        const typeLabel = card.type === 'patho'  ? 'Pathologie'  :
                          card.type === 'drug'   ? 'Médicament'  :
                          card.type === 'physio' ? 'Physiologie' : 'Donnée';

        const front = `
            <div style="font-family: -apple-system, sans-serif; text-align: center; padding: 16px;">
                <span style="font-size: 11px; color: #888; text-transform: uppercase; letter-spacing: 1.5px; font-weight: 600;">${typeLabel}</span>
                <h2 style="margin: 8px 0 0; font-size: 22px; color: #1e293b;">${card.title}</h2>
                ${card.subtitle ? `<p style="margin: 6px 0 0; font-size: 14px; color: #64748b;">${card.subtitle}</p>` : ''}
            </div>
        `;

        const htmlContent = renderToStaticMarkup(
            <ReactMarkdown remarkPlugins={[remarkGfm]}>
                {card.content || ''}
            </ReactMarkdown>
        );
        const back = `
            <div style="font-family: -apple-system, sans-serif; text-align: left; line-height: 1.6; padding: 8px 16px;">
                ${htmlContent}
            </div>
        `;

        const tags: string[] = [];
        if (card.type) tags.push(card.type);
        if (card.tags && Array.isArray(card.tags)) {
            // Anki tags cannot contain spaces — replace with underscores
            tags.push(...card.tags.map(t => t.replace(/\s+/g, '_')));
        }

        d.addNote(m.note([front, back], tags));
    }

    const p = new Package();
    p.setSqlJs(SQL);
    p.addDeck(d);

    // .export() returns Uint8Array or ArrayBuffer depending on jszip config in genanki-js
    // @ts-expect-error genanki-js typings are incomplete
    const zipBuffer = await p.export();
    const blob = new Blob([zipBuffer], { type: 'application/octet-stream' });

    const safeName = deckName.replace(/[^a-zA-Z0-9_\-]/g, '_');
    saveAs(blob, `${safeName}.apkg`);
}

import Papa from 'papaparse';
import type { Card, CardType } from '../types';

type ImportCandidate = Partial<Card> & Record<string, unknown>;

export const pickString = (...values: unknown[]): string => {
    const first = values.find((v): v is string => typeof v === 'string' && v.trim().length > 0);
    return first ? first : '';
};

export const sanitizeText = (text: string): string => text.replace(/[\u200B-\u200D\uFEFF]/g, '').trim();

export const generateSafeId = (title: string): string => {
    return sanitizeText(title).toLowerCase()
        .replace(/[^a-z0-9à-ÿ]+/gi, '-')
        .replace(/^-+|-+$/g, '');
};

export const parseTextFormat = (text: string, defaultCardType: CardType, groupName: string): Card[] => {
    const cards: Card[] = [];
    const lines = text.split('\n');

    const rawSections: { type: 'course' | 'concept' | 'flashcard', lines: string[] }[] = [];
    let currentSection: { type: 'course' | 'concept' | 'flashcard', lines: string[] } | null = null;

    lines.forEach(line => {
        const trimmed = line.trim();
        if (trimmed.startsWith('# ') || trimmed.startsWith('## ') || trimmed.startsWith('### ')) {
            if (currentSection) {
                rawSections.push(currentSection);
            }
            let type: 'course' | 'concept' | 'flashcard' = 'flashcard';
            if (trimmed.startsWith('# ')) type = 'course';
            else if (trimmed.startsWith('## ')) type = 'concept';

            currentSection = {
                type,
                lines: [trimmed.replace(/^#+\s*/, '')]
            };
        } else {
            if (currentSection) {
                currentSection.lines.push(line);
            } else if (trimmed.length > 0) {
                currentSection = { type: 'flashcard', lines: [line] };
            }
        }
    });
    if (currentSection) {
        rawSections.push(currentSection);
    }

    let lastCourseId: string | undefined = undefined;
    let lastConceptId: string | undefined = undefined;

    rawSections.forEach(section => {
        if (section.lines.length === 0) return;

        const rawTitle = section.lines[0].trim();
        if (!rawTitle) return;

        const title = sanitizeText(rawTitle);
        const extractedTags: string[] = [];
        const extractedLinks: string[] = [];
        let subject = '';

        let subtitle = '';
        const contentLines: string[] = [];

        let parsingMetadata = true;
        let subtitleFound = false;

        section.lines.slice(1).forEach(line => {
            const trimmed = line.trim();

            if (parsingMetadata) {
                const tagMatch = trimmed.match(/^\[([^\]]+)\]$/);
                const subjectMatch = trimmed.match(/^(?:Subject|Matière|Matiere|Module|Type)\s*:\s*(.+)$/i);
                const linkMatch = trimmed.match(/^(?:Liens|Links|Cartes [Ll]i[ée]es)\s*:\s*(.+)$/i);

                if (tagMatch) {
                    const tags = tagMatch[1].split(',').map(t => sanitizeText(t.trim())).filter(Boolean);
                    extractedTags.push(...tags);
                    return;
                } else if (subjectMatch) {
                    subject = sanitizeText(subjectMatch[1]);
                    return;
                } else if (linkMatch) {
                    const links = linkMatch[1].split(',').map(t => sanitizeText(t.trim())).filter(Boolean);
                    extractedLinks.push(...links);
                    return;
                } else if (trimmed === '') {
                    return;
                } else if (!subtitleFound && !trimmed.startsWith('##')) {
                    subtitle = sanitizeText(trimmed);
                    subtitleFound = true;
                    return;
                } else {
                    parsingMetadata = false;
                }
            }
            contentLines.push(line);
        });

        const details = contentLines.join('\n').trim();
        // Generate a random suffix to avoid collisions in mass imports with similar names
        const id = generateSafeId(title) + '-' + Math.random().toString(36).substring(2, 6);

        let parentId: string | undefined = undefined;
        if (section.type === 'course') {
            lastCourseId = id;
            lastConceptId = undefined;
        } else if (section.type === 'concept') {
            lastConceptId = id;
            parentId = lastCourseId;
        } else if (section.type === 'flashcard') {
            parentId = lastConceptId || lastCourseId;
        }

        let resolvedType = defaultCardType;
        if (subject && ['drug', 'patho', 'physio', 'data', 'concept'].includes(subject.toLowerCase())) {
            resolvedType = subject.toLowerCase() as CardType;
        }

        cards.push({
            id,
            type: resolvedType,
            nodeType: section.type,
            ...(section.type === 'flashcard' ? { format: 'q&a' } : {}),
            ...(parentId ? { parentId } : {}),
            title,
            subtitle,
            content: details || subtitle,
            details: details || subtitle,
            tags: [
                ...extractedTags,
                ...(groupName.trim() ? [`_group:${groupName.trim()}`] : [])
            ],
            manualConnections: extractedLinks.length > 0 ? extractedLinks : undefined,
            subject: subject || undefined,
        });
    });

    return cards;
};

export const parseJsonFormat = (jsonString: string, defaultCardType: CardType, groupName: string): Card[] => {
    const parsed = JSON.parse(jsonString);
    let validCards: ImportCandidate[] = [];

    if (Array.isArray(parsed)) {
        validCards = parsed.filter((c: ImportCandidate) => !!pickString(c.title, c.Title, c.name, c.Name));
    } else if (typeof parsed === 'object' && parsed !== null) {
        const parsedCandidate = parsed as ImportCandidate;
        if (pickString(parsedCandidate.title, parsedCandidate.Title, parsedCandidate.name, parsedCandidate.Name)) {
            validCards = [parsed];
        }
    } else {
        throw new Error("Le JSON doit être un tableau d'objets ou un objet unique.");
    }

    return validCards.map((c) => {
        const title = sanitizeText(pickString(c.title, c.Title, c.name, c.Name));
        return {
            ...c,
            id: pickString(c.id) ? sanitizeText(pickString(c.id)) : generateSafeId(title),
            title: title,
            type: (pickString(c.type) as CardType) || defaultCardType,
            tags: [
                ...(Array.isArray(c.tags) ? c.tags.filter((t): t is string => typeof t === 'string') : []),
                ...(groupName.trim() ? [`_group:${groupName.trim()}`] : [])
            ],
            subtitle: sanitizeText(pickString(c.subtitle)),
            content: sanitizeText(pickString(c.content)),
            details: sanitizeText(pickString(c.details, c.content)),
            subject: pickString(c.subject, c.Subject, c.matiere, c.Matiere, c.module, c.Module) ? sanitizeText(pickString(c.subject, c.Subject, c.matiere, c.Matiere, c.module, c.Module)) : undefined,
        } as Card;
    });
};

export const parseCsvFormat = (csvString: string, defaultCardType: CardType, groupName: string): Card[] => {
    // We will auto-detect the delimiter with PapaParse
    const parsed = Papa.parse(csvString, {
        header: true,
        skipEmptyLines: true,
        transformHeader: (header) => header.trim().toLowerCase()
    });

    if (parsed.errors && parsed.errors.length > 0 && parsed.data.length === 0) {
        throw new Error(`Erreur CSV: ${parsed.errors[0].message}`);
    }

    // In case no header matches typical names, we fallback to array mode if needed, but header:true is best for CSV/TSV from Anki/Excel
    const validCards: Card[] = [];

    parsed.data.forEach((row: any, index) => {
        // Try to identify Title, Content, Tags from columns
        // Common Anki exports or simple Excel headers: Title, Name, Front, Recto / Content, Description, Back, Verso / Tags
        const title = pickString(row.title, row.titre, row.name, row.nom, row.front, row.recto, row['col 1'], row.concept);
        if (!title) return; // skip row if no title

        const content = pickString(row.content, row.contenu, row.description, row.back, row.verso, row.details, row['col 2'], row.définition);
        const tagsRaw = pickString(row.tags, row.tag, row.étiquettes, row.categories);

        const tags = tagsRaw ? tagsRaw.split(',').map(t => sanitizeText(t)).filter(Boolean) : [];
        const subject = pickString(row.subject, row.matiere, row.matière, row.module, row.course, row.cours);

        validCards.push({
            id: generateSafeId(title) + '-' + index, // Add index to avoid ID collision if same title
            type: defaultCardType,
            title: sanitizeText(title),
            subtitle: '',
            content: sanitizeText(content),
            details: sanitizeText(content),
            tags: [
                ...tags,
                ...(groupName.trim() ? [`_group:${groupName.trim()}`] : [])
            ],
            subject: subject ? sanitizeText(subject) : undefined,
        } as Card);
    });

    if (validCards.length === 0 && parsed.data.length > 0) {
        // If we have rows but no valid cards, it might be a headerless CSV
        // Let's parse without header
        const fallbackParsed = Papa.parse(csvString, { header: false, skipEmptyLines: true });
        fallbackParsed.data.forEach((row: any, index) => {
            if (!Array.isArray(row) || row.length === 0) return;
            const title = pickString(row[0]);
            if (!title) return;

            const content = row.length > 1 ? pickString(row[1]) : '';
            const tags = row.length > 2 ? pickString(row[2]).split(',').map(t => sanitizeText(t)).filter(Boolean) : [];

            validCards.push({
                id: generateSafeId(title) + '-' + index,
                type: defaultCardType,
                title: sanitizeText(title),
                subtitle: '',
                content: sanitizeText(content),
                details: sanitizeText(content),
                tags: [
                    ...tags,
                    ...(groupName.trim() ? [`_group:${groupName.trim()}`] : [])
                ]
            } as Card);
        });
    }

    return validCards;
};

// @ts-nocheck
import { z } from 'zod';
import type { Card } from '../types';

/** Maximum allowed length for string fields to prevent oversized imports */
const MAX_TITLE_LENGTH = 300;
const MAX_CONTENT_LENGTH = 50_000;
const MAX_DETAILS_LENGTH = 200_000;
const MAX_SUBTITLE_LENGTH = 500;
const MAX_TAG_LENGTH = 100;
const MAX_TAGS_COUNT = 50;
const MAX_BATCH_SIZE = 2_000;

/** Regex to detect script injection patterns in content strings */
const SCRIPT_INJECTION_RE = /<\s*script[\s>]/i;
const DANGEROUS_PROTO_RE = /javascript\s*:/i;

/** Strip invisible / zero-width characters that can corrupt IDs:
 *  \u0000-\u0008  – C0 control characters (NUL..BS)
 *  \u000B-\u000C  – VT, FF
 *  \u000E-\u001F  – SO..US (remaining C0 controls)
 *  \u007F         – DEL
 *  \u200B-\u200D  – Zero-width space/non-joiner/joiner
 *  \uFEFF         – BOM / zero-width no-break space
 */
const sanitizeString = (s: string): string => s.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F\u200B-\u200D\uFEFF]/g, '').trim();

// Zod Schema for strict validation
export const CardSchema = z.object({
    id: z.string().min(1, "ID is required").max(200, "ID too long").transform(sanitizeString),
    title: z.string().min(1, "Title is required").max(MAX_TITLE_LENGTH, `Title exceeds ${MAX_TITLE_LENGTH} chars`).transform(sanitizeString),
    type: z.enum(['drug', 'patho', 'physio', 'data'] as const).default('data'),
    subtitle: z.string().max(MAX_SUBTITLE_LENGTH, `Subtitle exceeds ${MAX_SUBTITLE_LENGTH} chars`).transform(sanitizeString).optional(),
    content: z.string().max(MAX_CONTENT_LENGTH, `Content exceeds ${MAX_CONTENT_LENGTH} chars`).optional(),
    details: z.string().max(MAX_DETAILS_LENGTH, `Details exceeds ${MAX_DETAILS_LENGTH} chars`).optional(),
    tags: z.array(
        z.string().max(MAX_TAG_LENGTH, `Tag exceeds ${MAX_TAG_LENGTH} chars`).transform(sanitizeString)
    ).max(MAX_TAGS_COUNT, `Too many tags (max ${MAX_TAGS_COUNT})`).default([]),
    imageUrl: z.string().url("Invalid image URL").optional().or(z.literal('')),
    manualConnections: z.array(z.string().max(200)).max(500, "Too many manual connections").optional(),
    subject: z.string().max(100, "Subject too long").transform(sanitizeString).optional(),
});

export const ImportBatchSchema = z.array(CardSchema).max(MAX_BATCH_SIZE, `Batch exceeds max size of ${MAX_BATCH_SIZE} cards`);

export type ValidationResult = {
    success: boolean;
    errors: string[];
    validCards: Card[];
    warnings: string[];
};

/**
 * Checks whether a string contains dangerous script injection patterns.
 */
function containsInjection(value: string): boolean {
    return SCRIPT_INJECTION_RE.test(value) || DANGEROUS_PROTO_RE.test(value);
}

/**
 * Deep-scans all string fields of a raw card object for injection patterns.
 * Returns a list of field names that are suspicious.
 */
function detectInjectionFields(raw: Record<string, unknown>): string[] {
    const suspicious: string[] = [];
    const stringFields: (keyof typeof raw)[] = ['title', 'subtitle', 'content', 'details', 'id'];
    for (const field of stringFields) {
        const val = raw[field];
        if (typeof val === 'string' && containsInjection(val)) {
            suspicious.push(String(field));
        }
    }
    if (Array.isArray(raw.tags)) {
        (raw.tags as unknown[]).forEach((tag, i) => {
            if (typeof tag === 'string' && containsInjection(tag)) {
                suspicious.push(`tags[${i}]`);
            }
        });
    }
    return suspicious;
}

/**
 * Validates a batch of imported data against the schema
 * @param data Raw JSON or object data
 */
export function validateImportData(data: unknown): ValidationResult {
    const warnings: string[] = [];

    try {
        // Ensure array
        const arrayData = Array.isArray(data) ? data : [data];

        // Pre-validation: size guard
        if (arrayData.length > MAX_BATCH_SIZE) {
            return {
                success: false,
                errors: [`Import batch too large: ${arrayData.length} cards (max ${MAX_BATCH_SIZE})`],
                validCards: [],
                warnings: [],
            };
        }

        // Pre-validation: check for injection attempts and duplicate IDs
        const seenIds = new Set<string>();
        const duplicateIds: string[] = [];

        for (let i = 0; i < arrayData.length; i++) {
            const raw = arrayData[i];
            if (typeof raw !== 'object' || raw === null) continue;

            const rawObj = raw as Record<string, unknown>;

            // Injection detection
            const badFields = detectInjectionFields(rawObj);
            if (badFields.length > 0) {
                return {
                    success: false,
                    errors: [`Card at index ${i}: dangerous content detected in fields: ${badFields.join(', ')}`],
                    validCards: [],
                    warnings: [],
                };
            }

            // Duplicate ID detection
            const rawId = typeof rawObj.id === 'string' ? rawObj.id.trim() : null;
            if (rawId) {
                if (seenIds.has(rawId)) {
                    duplicateIds.push(rawId);
                } else {
                    seenIds.add(rawId);
                }
            }
        }

        if (duplicateIds.length > 0) {
            warnings.push(`Duplicate IDs found (will be deduplicated): ${duplicateIds.slice(0, 5).join(', ')}${duplicateIds.length > 5 ? ` (+${duplicateIds.length - 5} more)` : ''}`);
        }

        // Parse with Zod
        const parsed = ImportBatchSchema.parse(arrayData);

        // Post-parse deduplication by ID (keep last occurrence, matching upsert semantics)
        const deduped = new Map<string, Card>();
        for (const card of parsed) {
            deduped.set(card.id, card as Card);
        }

        return {
            success: true,
            errors: [],
            validCards: Array.from(deduped.values()),
            warnings,
        };
    } catch (e: unknown) {
        if (e instanceof z.ZodError) {
            const zodError = e as z.ZodError<unknown>;
            const formattedErrors = zodError.issues.map((err: z.ZodIssue) => {
                const path = err.path.join('.');
                return `Field '${path}': ${(err as Error).message}`;
            });
            return {
                success: false,
                errors: formattedErrors,
                validCards: [],
                warnings,
            };
        }
        return {
            success: false,
            errors: [(e as Error).message],
            validCards: [],
            warnings,
        };
    }
}

/**
 * Embedding Worker - Computes text embeddings using Transformers.js
 * Runs in a Web Worker to avoid blocking the main thread
 */

import { pipeline, FeatureExtractionPipeline, env } from '@huggingface/transformers';

// Skip local model checks (fixes Electron worker fs issues)
env.allowLocalModels = false;
env.useBrowserCache = true;

// Suppress ONNX runtime warnings (like VerifyEachNodeIsAssignedToAnEp)
if (env.backends?.onnx) {
    env.backends.onnx.logLevel = 'fatal';
}

let extractor: FeatureExtractionPipeline | null = null;
let isLoading = false;

// Model: paraphrase-multilingual-MiniLM-L12-v2 (Better for symmetric similarity & French)
const MODEL_ID = 'Xenova/paraphrase-multilingual-MiniLM-L12-v2';

interface WorkerMessage {
    type: 'init' | 'embed' | 'embedBatch';
    id?: string;
    text?: string;
    texts?: string[];
    cardIds?: string[];
}

interface WorkerResponse {
    type: 'ready' | 'embedding' | 'embeddings' | 'progress' | 'error';
    id?: string;
    embedding?: number[];
    embeddings?: { cardId: string; embedding: number[] }[];
    progress?: number;
    error?: string;
}

// Initialize the model
async function initModel() {
    if (extractor || isLoading) return;

    isLoading = true;
    self.postMessage({ type: 'progress', progress: 0 } as WorkerResponse);

    try {
        // Try WebGPU first (fastest)
        extractor = await pipeline('feature-extraction', MODEL_ID, {
            device: 'webgpu',

            progress_callback: (progress: { status: string; name?: string; file?: string; progress?: number; }) => {
                if (typeof progress?.progress === 'number') {
                    self.postMessage({ type: 'progress', progress: progress.progress } as WorkerResponse);
                }
            },
            dtype: 'fp32' // WebGPU usually requires fp32 or fp16, not q8
        }) as FeatureExtractionPipeline;

        self.postMessage({ type: 'ready' } as WorkerResponse);
    } catch (webGpuError) {
        try {
            // Fallback to WASM (q8 quantization for efficiency)
            // @ts-ignore
            extractor = await pipeline('feature-extraction', MODEL_ID, {
                device: 'wasm',
                // quantized: true, // Removed as it's not a valid property, dtype handles it
                // @ts-ignore
                progress_callback: (progress: { status: string; name?: string; file?: string; progress?: number; }) => {
                    if (typeof progress?.progress === 'number') {
                        self.postMessage({ type: 'progress', progress: progress.progress } as WorkerResponse);
                    }
                },
                dtype: 'q8'
            }) as FeatureExtractionPipeline;

            self.postMessage({ type: 'ready' } as WorkerResponse);
        } catch (cpuError) {
            self.postMessage({ type: 'error', error: String(cpuError) } as WorkerResponse);
        }
    } finally {
        isLoading = false;
    }
}

// Generate embedding for a single text
async function generateEmbedding(text: string, id?: string) {
    if (!extractor) {
        await initModel();
    }

    if (!extractor) {
        self.postMessage({ type: 'error', error: 'Model not loaded' } as WorkerResponse);
        return;
    }

    try {
        // MiniLM-L12-v2 is symmetric, no prefix needed
        const prefixedText = text;
        const output = await extractor(prefixedText, { pooling: 'mean', normalize: true });

        // Convert to regular array
        const embedding = Array.from(output.data as Float32Array);

        self.postMessage({ type: 'embedding', id, embedding } as WorkerResponse);
    } catch (error) {
        self.postMessage({ type: 'error', error: String(error), id } as WorkerResponse);
    }
}

// Generate embeddings for batch of texts (more efficient)
async function generateBatchEmbeddings(texts: string[], cardIds: string[], id?: string) {
    if (!extractor) {
        await initModel();
    }

    if (!extractor) {
        self.postMessage({ type: 'error', error: 'Model not loaded' } as WorkerResponse);
        return;
    }

    const embeddings: { cardId: string; embedding: number[] }[] = [];

    try {
        for (let i = 0; i < texts.length; i++) {
            const prefixedText = texts[i];
            const output = await extractor(prefixedText, { pooling: 'mean', normalize: true });

            embeddings.push({
                cardId: cardIds[i],
                embedding: Array.from(output.data as Float32Array)
            });

            // Report progress
            if (i % 10 === 0 || i === texts.length - 1) {
                self.postMessage({
                    type: 'progress',
                    id,
                    progress: ((i + 1) / texts.length) * 100
                } as WorkerResponse);
            }
        }

        self.postMessage({ type: 'embeddings', id, embeddings } as WorkerResponse);
    } catch (error) {
        self.postMessage({ type: 'error', id, error: String(error) } as WorkerResponse);
    }
}

// Handle messages from main thread
self.onmessage = async (e: MessageEvent<WorkerMessage>) => {
    const { type, id, text, texts, cardIds } = e.data;

    switch (type) {
        case 'init':
            await initModel();
            break;
        case 'embed':
            if (text) await generateEmbedding(text, id);
            break;
        case 'embedBatch':
            if (texts && cardIds) await generateBatchEmbeddings(texts, cardIds, id);
            break;
    }
};
